// Flashcard deck for CompTIA CySA+ (CS0-004, V4). Each term is tagged with an objective id from objectives.js.

export const TERMS = [
  // 1.1 Explain system and network architecture concepts in security operations
  { term: "NTP", definition: "Network Time Protocol: synchronizes clocks across systems over UDP port 123. Consistent time is essential for correlating logs and building incident timelines.", objective: "1.1" },
  { term: "Syslog", definition: "A standard for sending log messages to a central collector, traditionally over UDP 514 (or TCP 6514 with TLS). Messages carry a facility and a severity from 0 (Emergency) to 7 (Debug).", objective: "1.1" },
  { term: "Windows Registry", definition: "Hierarchical database of Windows configuration settings organized under root keys such as HKLM and HKCU. Attackers modify keys like Run and Services for persistence.", objective: "1.1" },
  { term: "Hardening", definition: "Reducing a system's attack surface by removing unneeded services and software, closing ports, changing defaults, patching and applying a secure configuration baseline.", objective: "1.1" },
  { term: "Hypervisor", definition: "Software that creates and runs virtual machines. Type 1 runs directly on hardware (bare-metal); Type 2 runs on top of a host operating system.", objective: "1.1" },
  { term: "VM escape", definition: "An attack in which code running inside a virtual machine breaks out to interact with the hypervisor or other VMs on the same host.", objective: "1.1" },
  { term: "Containerization", definition: "Packaging an application with its dependencies into an isolated container that shares the host OS kernel. Lighter than a VM but with weaker isolation.", objective: "1.1" },
  { term: "Serverless", definition: "A cloud model (functions as a service) where the provider runs code on demand and manages all servers. Customers cannot install agents, so monitoring depends on provider logs.", objective: "1.1" },
  { term: "SDN", definition: "Software-Defined Networking: separates the control plane (central controller deciding traffic flow) from the data plane (devices forwarding packets), allowing networks to be managed through software and APIs.", objective: "1.1" },
  { term: "Zero trust", definition: "Security model that grants no implicit trust based on network location. Every access request is authenticated, authorized and continuously evaluated using identity, device and context.", objective: "1.1" },
  { term: "SASE", definition: "Secure Access Service Edge: cloud-delivered architecture combining SD-WAN networking with security services such as SWG, CASB, ZTNA and firewall-as-a-service.", objective: "1.1" },
  { term: "CASB", definition: "Cloud Access Security Broker: enforces security policy between users and cloud services, providing visibility into shadow IT, DLP, access control and threat detection, via API or inline proxy.", objective: "1.1" },
  { term: "PAM", definition: "Privileged Access Management: controls and monitors administrative accounts through credential vaulting, password rotation, session recording and just-in-time elevation.", objective: "1.1" },
  { term: "Federation", definition: "A trust relationship that lets users authenticate with one identity provider and access services in another organization or domain, often using SAML or OpenID Connect.", objective: "1.1" },
  { term: "SAML", definition: "Security Assertion Markup Language: XML-based standard in which an identity provider sends signed assertions about a user to a service provider, enabling web single sign-on.", objective: "1.1" },
  { term: "OpenID Connect", definition: "An authentication layer built on OAuth 2.0 that issues a JSON Web Token (ID token) describing the authenticated user.", objective: "1.1" },
  { term: "Passwordless authentication", definition: "Logging in without a shared password, for example with FIDO2 security keys, passkeys or biometrics backed by public-key cryptography. Resists phishing and credential stuffing.", objective: "1.1" },
  { term: "PKI", definition: "Public Key Infrastructure: the certificate authorities, policies and processes that issue, manage and revoke digital certificates binding public keys to identities.", objective: "1.1" },
  { term: "TLS inspection", definition: "Decrypting TLS traffic at a proxy or firewall, inspecting it, then re-encrypting it with a certificate from an internal CA trusted by clients. Restores visibility into encrypted threats.", objective: "1.1" },
  { term: "DLP", definition: "Data Loss Prevention: technology that identifies sensitive data at rest, in motion and in use and blocks, alerts on or encrypts it to prevent unauthorized disclosure.", objective: "1.1" },
  { term: "PII", definition: "Personally Identifiable Information: data that can identify an individual on its own or combined with other data, such as name, Social Security number or date of birth.", objective: "1.1" },
  { term: "Cardholder data", definition: "Under PCI DSS, the primary account number (PAN) plus cardholder name, expiration date and service code. Sensitive authentication data like CVV2 must not be stored after authorization.", objective: "1.1" },
  { term: "TPM", definition: "Trusted Platform Module: a hardware chip that securely stores keys and measures the boot process, supporting features like disk encryption and attestation.", objective: "1.1" },
  { term: "ICS", definition: "Industrial Control System: the subset of operational technology that automates industrial processes, made up of components such as PLCs, HMIs, control servers, historians and SCADA or DCS systems.", objective: "1.1" },
  { term: "SCADA", definition: "Supervisory Control and Data Acquisition: an ICS that supervises many geographically distributed sites, such as pipelines and power grids, over a WAN using a central master (MTU) and field RTUs. Contrast with a DCS, which controls a single site.", objective: "1.1" },
  { term: "PLC", definition: "Programmable Logic Controller: a ruggedized, single-purpose industrial controller that reads sensors and drives actuators in fast control loops, typically programmed in ladder logic and with very limited logging.", objective: "1.1" },
  { term: "Continuous monitoring", definition: "An ongoing program of near real-time collection and analysis of security telemetry across network, endpoint, cloud, application and identity sources, aimed at shortening attacker dwell time.", objective: "1.1" },
  { term: "Baseline (security)", definition: "A documented picture of normal behavior, such as login times, egress volume, expected processes and API call rates, against which anomalies are detected. Must be refreshed as the environment changes.", objective: "1.1" },
  { term: "Shared responsibility model", definition: "The division of security duties between a cloud provider and its customer. The provider secures the underlying infrastructure; the customer always remains responsible for its data, identities, configuration and monitoring.", objective: "1.1" },
  { term: "Microservices", definition: "An architecture of small, independent services that communicate over APIs. Compromise is more contained, but the number of components and service-to-service calls to monitor grows sharply.", objective: "1.1" },
  { term: "Infrastructure as Code (IaC)", definition: "Defining cloud resources in templates (Terraform, CloudFormation, Ansible) that are deployed automatically. One insecure template line can create many misconfigured resources, so templates are scanned before deployment.", objective: "1.1" },
  { term: "Control plane", definition: "In SDN and cloud platforms, the layer that decides how traffic is handled or resources are configured (for example a central SDN controller or cloud management APIs), as opposed to the data plane that forwards traffic.", objective: "1.1" },
  { term: "Data plane", definition: "The layer of network devices that actually forwards packets according to decisions made by the control plane. The management plane is used to configure and monitor both.", objective: "1.1" },
  { term: "VM sprawl", definition: "Uncontrolled growth of virtual machines that are forgotten, unpatched or left with default credentials. Found by comparing scanner results with the asset inventory.", objective: "1.1" },
  { term: "East-west traffic", definition: "Traffic between systems inside the same environment (server to server, VM to VM) rather than in and out of it. It often bypasses perimeter controls, so it requires microsegmentation and internal visibility.", objective: "1.1" },
  { term: "Microsegmentation", definition: "Applying fine-grained security policy between individual workloads or applications so that inter-zone traffic needs explicit permission, limiting lateral movement.", objective: "1.1" },
  { term: "Kubernetes", definition: "An open-source platform for orchestrating containers at scale. Key risks include permissive RBAC, an exposed API server, containers running as root and plaintext secrets; its audit log records every API server request.", objective: "1.1" },
  { term: "Falco", definition: "Open-source runtime security tool that watches container and host syscalls and alerts on suspicious behavior, such as a shell spawned inside a production container.", objective: "1.1" },
  { term: "BOLA", definition: "Broken Object Level Authorization: an API flaw where changing an object ID in a request (for example a user number) returns another user's data. The most common issue in the OWASP API Security Top 10.", objective: "1.1" },
  { term: "API gateway", definition: "A front door for APIs (e.g. AWS API Gateway, Kong, Apigee) that centralizes authentication, authorization, rate limiting and logging, making it the main API control and telemetry point.", objective: "1.1" },
  { term: "MDM", definition: "Mobile Device Management: centrally manages entire devices, pushing configuration, enforcing policy and allowing remote lock and wipe. Enrollment and compliance status feed conditional access.", objective: "1.1" },
  { term: "MAM", definition: "Mobile Application Management: manages only corporate apps and their data on a device, allowing selective wipe without controlling the rest of the device. The usual choice for BYOD.", objective: "1.1" },
  { term: "UEM", definition: "Unified Endpoint Management: a single console that manages and reports compliance for all device types, including desktops, laptops, phones and tablets.", objective: "1.1" },
  { term: "Mobile threat defense (MTD)", definition: "Software that actively detects threats on mobile devices, such as malicious apps, network attacks and OS exploits. Complements MDM, which handles management and compliance.", objective: "1.1" },
  { term: "Conditional access", definition: "Policies that evaluate each sign-in using signals such as user, device compliance, location, application and risk, then allow, block or require extra verification. A core zero trust control.", objective: "1.1" },
  { term: "Deperimeterization", definition: "The erosion of the traditional network perimeter driven by cloud adoption, remote work, mobile devices and third-party access, which shifts trust to identity and segmentation.", objective: "1.1" },
  { term: "ZTNA", definition: "Zero Trust Network Access: grants users access to specific applications after verifying identity and device posture, re-evaluating continuously. Unlike a VPN, it does not place users on the network.", objective: "1.1" },
  { term: "SD-WAN", definition: "Software-defined WAN: intelligently routes traffic across broadband, LTE and MPLS links. Combined with cloud security services it forms SASE.", objective: "1.1" },
  { term: "Secure web gateway (SWG)", definition: "A proxy service that filters web traffic with URL filtering, malware scanning and TLS inspection, logging URL, user, time and allow/block decisions.", objective: "1.1" },
  { term: "Firewall as a service (FWaaS)", definition: "Firewall policy delivered from the cloud so the same rules apply to users wherever they connect; a component of SASE.", objective: "1.1" },
  { term: "Transit gateway", definition: "A cloud hub (e.g. AWS Transit Gateway, Azure Virtual WAN) that routes between many VPCs and on-prem networks. A chokepoint and high-value target whose route changes can widen lateral movement.", objective: "1.1" },
  { term: "Critical infrastructure", definition: "Systems and assets so vital that their disruption would threaten national security, public health or the economy. CISA groups them into 16 sectors, such as energy, water and healthcare.", objective: "1.1" },
  { term: "Operational technology (OT)", definition: "Hardware and software that monitor and control physical processes and equipment such as valves, pumps and turbines. Availability and safety take priority over confidentiality.", objective: "1.1" },
  { term: "IT/OT convergence", definition: "The connection of formerly isolated OT networks to IT networks and the cloud for monitoring and analytics, which exposes legacy industrial systems to IT threats.", objective: "1.1" },
  { term: "Purdue Model", definition: "A reference architecture that layers industrial networks from physical process (Level 0) through PLCs, HMIs and supervisory systems, site operations and an industrial DMZ, up to enterprise IT.", objective: "1.1" },
  { term: "HMI", definition: "Human-Machine Interface: the operator console used to monitor and control an industrial process. Often an aging, hard-to-patch Windows system that bridges IT and OT.", objective: "1.1" },
  { term: "Data historian", definition: "A time-series database that records process values from an industrial control system. A key forensic source for reconstructing what equipment did and when.", objective: "1.1" },
  { term: "RTU", definition: "Remote Terminal Unit: a ruggedized field device, similar to a PLC, that collects data and controls equipment at remote SCADA sites and reports over a WAN.", objective: "1.1" },
  { term: "DCS", definition: "Distributed Control System: an ICS that automates processes within a single facility, such as a refinery or power plant, as opposed to SCADA, which spans many distributed sites.", objective: "1.1" },
  { term: "Modbus", definition: "A widely used, legacy industrial protocol (TCP 502) with no authentication or encryption, so any host that can reach a device can read or write values.", objective: "1.1" },
  { term: "DNP3", definition: "Distributed Network Protocol 3: an industrial protocol (port 20000) used by power and water utilities for master stations to poll RTUs and outstations. Security features are limited and optional.", objective: "1.1" },
  { term: "OPC UA", definition: "A modern industrial interoperability protocol with built-in authentication, signing and encryption, unlike legacy protocols such as Modbus.", objective: "1.1" },
  { term: "Industrial DMZ (IDMZ)", definition: "A buffer zone between enterprise IT and the OT network through which all IT/OT traffic must pass, so no corporate host talks directly to control devices.", objective: "1.1" },
  { term: "Data diode", definition: "A hardware unidirectional gateway that physically allows data to flow in only one direction, typically from OT to IT, with no possible return path.", objective: "1.1" },
  { term: "Safety instrumented system (SIS)", definition: "An independent control system that automatically brings an industrial process to a safe state when dangerous conditions occur. Attacks on it are the highest severity.", objective: "1.1" },
  { term: "Stuxnet", definition: "Malware discovered in 2010 that altered Siemens PLC logic controlling Iranian centrifuges while showing operators normal readings; the classic example of a spoofed process value attack.", objective: "1.1" },
  { term: "MITRE ATT&CK for ICS", definition: "The ATT&CK knowledge base for industrial control systems, with OT-specific tactics such as Inhibit Response Function and Impair Process Control.", objective: "1.1" },
  { term: "NIST SP 800-82", definition: "NIST's guide to operational technology (ICS) security, covering OT architecture, risks and recommended controls.", objective: "1.1" },
  { term: "IEC 62443", definition: "An international series of standards for securing industrial automation and control systems, used by asset owners, integrators and vendors.", objective: "1.1" },
  { term: "Rootkit", definition: "Malware that subverts the OS, often at the kernel level, to hide processes, files and network connections so that security tools see only what the attacker allows.", objective: "1.1" },
  { term: "Secure Boot", definition: "A UEFI feature that only loads bootloaders and OS components signed by trusted keys, blocking bootkits. Often combined with TPM-based measured boot.", objective: "1.1" },
  { term: "DoD STIG", definition: "Security Technical Implementation Guide: a DISA configuration baseline for hardening systems, required in US federal and defense environments and widely used elsewhere.", objective: "1.1" },
  { term: "Autoruns", definition: "A Sysinternals tool that lists every Windows auto-start location (Run keys, services, scheduled tasks, startup folders, drivers, browser extensions) in one view for persistence hunting.", objective: "1.1" },
  { term: "auditd", definition: "The Linux audit daemon, which records kernel-level events such as file access, syscalls and privilege use to /var/log/audit/audit.log according to configured rules.", objective: "1.1" },
  { term: "LOLBAS / GTFOBins", definition: "Community catalogs of legitimate binaries that can be abused for attacker purposes: LOLBAS for Windows and GTFOBins for Unix/Linux. Used to understand and detect living-off-the-land activity.", objective: "1.1" },
  { term: "Group Policy (GPO)", definition: "Active Directory mechanism for enforcing settings across domain computers and users. A compromised domain controller can push malicious GPOs; changes show as Event IDs 5136, 5137 and 5141.", objective: "1.1" },
  { term: "Application allowlisting", definition: "Permitting only approved executables to run. On Windows, AppLocker enforces it in user mode and WDAC is kernel-enforced and harder to bypass. A key compensating control for unpatchable systems.", objective: "1.1" },
  { term: "WDAC", definition: "Windows Defender Application Control: kernel-enforced application allowlisting that is stronger than AppLocker and also limits abuse of living-off-the-land binaries.", objective: "1.1" },
  { term: "Log normalization", definition: "Converting logs from different formats into a common schema with consistent field names so searches and correlation rules work across all sources.", objective: "1.1" },
  { term: "Immutable log storage", definition: "Write-once (WORM) storage, such as S3 Object Lock or Azure immutable Blob storage, that prevents anyone, including administrators, from modifying or deleting logs during the retention period.", objective: "1.1" },
  { term: "NTP stratum", definition: "The distance of a clock from a reference time source: stratum 0 is the reference clock, stratum 1 servers sync to it directly, and each hop adds one.", objective: "1.1" },
  { term: "Tiered log storage", definition: "Keeping recent logs in fast hot storage, older logs in cheaper warm storage and long-term logs in cold archives, often automated with lifecycle policies to meet retention at lower cost.", objective: "1.1" },
  { term: "Orphaned account", definition: "An account belonging to a departed user or retired purpose that was never disabled. It provides valid credentials nobody monitors and is found through access reviews and HR reconciliation.", objective: "1.1" },
  { term: "Just-in-time (JIT) access", definition: "Granting elevated privileges only for a specific task and limited time window, then removing them automatically, instead of leaving standing admin rights.", objective: "1.1" },
  { term: "Kerberoasting", definition: "An attack that requests Kerberos service tickets for accounts with SPNs and cracks them offline to recover service account passwords. Seen as bursts of Event ID 4769 from one account.", objective: "1.1" },
  { term: "DCSync", definition: "An attack in which an account with replication rights impersonates a domain controller to request password hashes from Active Directory.", objective: "1.1" },
  { term: "Separation of duties", definition: "Splitting critical tasks among different people so no single person can complete and conceal a sensitive action, e.g. approving versus checking out privileged credentials.", objective: "1.1" },
  { term: "MFA", definition: "Multifactor authentication: verification using two or more factors from different categories, such as something you know, have and are. SMS is the weakest method; FIDO2 hardware keys are the strongest.", objective: "1.1" },
  { term: "SSO", definition: "Single sign-on: authenticating once to access many applications. Reduces password fatigue, but a compromised SSO identity unlocks everything connected to it.", objective: "1.1" },
  { term: "OAuth 2.0", definition: "An authorization framework that issues access tokens so an application can act on a user's behalf. It does not authenticate the user by itself; OpenID Connect adds that layer.", objective: "1.1" },
  { term: "FIDO2", definition: "A passwordless standard (WebAuthn plus CTAP) using public-key credentials stored on a device or security key. Credentials are bound to the site's origin, making them phishing resistant.", objective: "1.1" },
  { term: "Mutual TLS (mTLS)", definition: "A TLS connection in which both client and server present and verify certificates, providing strong two-way authentication between systems.", objective: "1.1" },
  { term: "Crossover error rate (CER)", definition: "The point where a biometric system's false acceptance rate equals its false rejection rate. A lower CER means a more accurate system.", objective: "1.1" },
  { term: "DAC", definition: "Discretionary Access Control: the resource owner decides who gets access, as with NTFS file permissions. Flexible but prone to over-sharing and permission sprawl.", objective: "1.1" },
  { term: "MAC (Mandatory Access Control)", definition: "Access decided by system-enforced classification labels and clearances that users cannot override. Used in military and government systems and implemented by SELinux.", objective: "1.1" },
  { term: "RBAC", definition: "Role-Based Access Control: permissions are assigned to roles that match job functions, and users receive roles. The most common enterprise model.", objective: "1.1" },
  { term: "ABAC", definition: "Attribute-Based Access Control: access decided dynamically from attributes of the user, resource and environment (department, clearance, location, time, device). The basis for zero trust policies.", objective: "1.1" },
  { term: "Least privilege", definition: "Giving each user, service and process only the access it needs for its task and no more, limiting the damage if it is compromised.", objective: "1.1" },
  { term: "Secrets management", definition: "Storing passwords, keys, tokens and certificates in a central vault (e.g. HashiCorp Vault, AWS Secrets Manager, Azure Key Vault) that controls access, logs retrieval and rotates secrets automatically.", objective: "1.1" },
  { term: "Secret scanning", definition: "Searching code and its full Git history for exposed credentials with tools such as TruffleHog, Gitleaks or GitHub secret scanning, so leaked secrets can be revoked and rotated.", objective: "1.1" },
  { term: "Ephemeral credentials", definition: "Short-lived, automatically issued credentials (e.g. IAM roles for compute, Vault dynamic database users) that remove long-lived secrets an attacker could steal.", objective: "1.1" },
  { term: "PHI", definition: "Protected Health Information: individually identifiable health condition, treatment or payment data, governed in the US by HIPAA.", objective: "1.1" },
  { term: "Data states", definition: "The three conditions data exists in: at rest (stored), in transit (moving over a network) and in use (in memory being processed). Each needs different protections.", objective: "1.1" },
  { term: "Hashing", definition: "A one-way function that produces a fixed-length digest of data. Used to verify integrity and identify files; it cannot be reversed to recover the input.", objective: "1.1" },
  { term: "Encoding", definition: "Transforming data into another format, such as Base64, for compatibility. Anyone can reverse it without a key, so it provides no security.", objective: "1.1" },
  { term: "Symmetric encryption", definition: "Encryption that uses the same secret key to encrypt and decrypt. Fast and suited to bulk data (e.g. AES, ChaCha20), but the key must be exchanged securely.", objective: "1.1" },
  { term: "Asymmetric encryption", definition: "Encryption using a mathematically linked public and private key pair (e.g. RSA, ECC). Solves key exchange and enables signatures but is too slow for bulk data.", objective: "1.1" },
  { term: "AES", definition: "Advanced Encryption Standard: the standard symmetric block cipher, with 128, 192 or 256-bit keys, used for disk, database, cloud storage and TLS encryption.", objective: "1.1" },
  { term: "Diffie-Hellman", definition: "A key agreement method that lets two parties derive a shared secret over an untrusted network without sending the key itself. Its ephemeral forms (DHE/ECDHE) provide forward secrecy in TLS.", objective: "1.1" },
  { term: "ECC", definition: "Elliptic Curve Cryptography: asymmetric cryptography that achieves the same strength as RSA with much smaller keys (256-bit ECC is roughly equal to 3072-bit RSA).", objective: "1.1" },
  { term: "Digital signature", definition: "A hash of data signed with the sender's private key and verified with the public key. Provides integrity, authenticity and non-repudiation, but not confidentiality.", objective: "1.1" },
  { term: "Certificate authority (CA)", definition: "A trusted entity that verifies identities (with a registration authority) and signs digital certificates binding public keys to them.", objective: "1.1" },
  { term: "CRL", definition: "Certificate Revocation List: a periodically published, CA-signed list of certificate serial numbers that have been revoked before expiry.", objective: "1.1" },
  { term: "OCSP", definition: "Online Certificate Status Protocol: a real-time query to check whether a certificate has been revoked; faster than downloading a CRL. OCSP stapling lets the server supply the response.", objective: "1.1" },
  { term: "Certificate pinning", definition: "An application accepting only a specific certificate or public key for a server. It blocks interception, including legitimate TLS inspection, and malware can use it to evade inspection.", objective: "1.1" },
  { term: "TDE", definition: "Transparent Data Encryption: encrypts an entire database's files at rest without application changes. Column-level encryption instead protects only selected sensitive fields.", objective: "1.1" },
  { term: "Full-disk encryption (FDE)", definition: "Encrypting an entire drive, e.g. with BitLocker (backed by the TPM) or FileVault, so data at rest is unreadable if the device is lost or stolen.", objective: "1.1" },
  { term: "S/MIME", definition: "Email encryption and signing using X.509 certificates from a centralized PKI. Common in enterprises with existing certificate infrastructure.", objective: "1.1" },
  { term: "PGP", definition: "Pretty Good Privacy (OpenPGP): email and file encryption and signing based on a decentralized web of trust in which users sign each other's keys instead of relying on a CA.", objective: "1.1" },
  { term: "Key management", definition: "The lifecycle of cryptographic keys: generation, storage, distribution, rotation and revocation, ideally in a KMS or HSM kept separate from the data the keys protect.", objective: "1.1" },
  { term: "Data classification", definition: "Labeling data by sensitivity (e.g. Restricted, Internal, Public, or Top Secret to Unclassified) so that encryption, access controls, DLP rules and handling match its value.", objective: "1.1" },
  { term: "Data owner", definition: "The business leader accountable for a data set, who decides its classification and who may access it and accepts the associated risk.", objective: "1.1" },
  { term: "Data custodian", definition: "The IT or security function that implements and operates the technical controls (encryption, access control, backups, DLP) required by the data owner's decisions.", objective: "1.1" },
  { term: "Tokenization", definition: "Replacing sensitive data such as a card number with a non-sensitive surrogate value, keeping the real data in a secure vault. Commonly used to reduce PCI DSS scope.", objective: "1.1" },
  { term: "DNS tunneling", definition: "Encoding data or C2 traffic inside DNS queries and responses, typically visible as many queries to one domain with long, high-entropy subdomains.", objective: "1.1" },
  { term: "Event ID 4728", definition: "Windows Security event: a member was added to a security-enabled global group. Additions to privileged groups such as Domain Admins should be verified against change records.", objective: "1.1" },
  { term: "Event ID 4769", definition: "Windows Security event: a Kerberos service ticket was requested. Many requests for different SPNs from one account in a short window suggests Kerberoasting.", objective: "1.1" },
  { term: "Event ID 6416", definition: "Windows Security event: a new external device was recognized by the system. Useful for spotting USB-based data theft alongside endpoint DLP.", objective: "1.1" },

  // 1.2 Analyze indicators of potential malicious activity
  { term: "Beaconing", definition: "Regular, periodic outbound connections from a compromised host to command-and-control infrastructure to check for instructions. Often shows consistent timing and packet sizes.", objective: "1.2" },
  { term: "Jitter", definition: "Random variation added to a malware beacon interval so its callbacks are less regular and harder to spot with simple timing analysis.", objective: "1.2" },
  { term: "Rogue device", definition: "An unauthorized device connected to the network, such as an unapproved wireless access point, DHCP server or personal laptop.", objective: "1.2" },
  { term: "Port scan", definition: "Probing many ports on a single host to discover listening services. Shows in logs as one source contacting many ports in a short time.", objective: "1.2" },
  { term: "Sweep", definition: "Probing one port or sending pings across many hosts to discover which addresses are live or run a particular service.", objective: "1.2" },
  { term: "Data exfiltration", definition: "Unauthorized transfer of data out of an organization, often indicated by large or unusual outbound transfers, archive files in staging folders or DNS tunneling.", objective: "1.2" },
  { term: "Lateral movement", definition: "Techniques attackers use to move from one compromised system to others inside a network, often seen as unusual workstation-to-workstation SMB, RDP or WinRM traffic.", objective: "1.2" },
  { term: "Event ID 4624", definition: "Windows Security log event for a successful logon. The logon type field shows how (2 interactive, 3 network, 10 RDP and so on).", objective: "1.2" },
  { term: "Event ID 4625", definition: "Windows Security log event for a failed logon. Many in a short period suggest brute forcing or password spraying.", objective: "1.2" },
  { term: "Event ID 4672", definition: "Windows Security log event recording that special (administrative) privileges were assigned to a new logon session.", objective: "1.2" },
  { term: "Event ID 4688", definition: "Windows Security log event for new process creation. With command-line auditing enabled, it shows the full command executed.", objective: "1.2" },
  { term: "Event ID 4720", definition: "Windows Security log event recording that a user account was created. Unexpected entries may indicate attacker persistence.", objective: "1.2" },
  { term: "Event ID 7045", definition: "Windows System log event recording that a new service was installed, commonly generated by PsExec and malware that persists as a service.", objective: "1.2" },
  { term: "Event ID 1102", definition: "Windows Security log event recording that the audit log was cleared, a common anti-forensics indicator.", objective: "1.2" },
  { term: "Event ID 4698", definition: "Windows Security log event recording that a scheduled task was created, which can reveal persistence.", objective: "1.2" },
  { term: "Password spraying", definition: "Trying one or a few common passwords against many accounts to avoid account lockout thresholds.", objective: "1.2" },
  { term: "Timestomping", definition: "Altering a file's timestamps so malicious files blend in with legitimate ones and confuse forensic timelines.", objective: "1.2" },
  { term: "Alternate data stream", definition: "An NTFS feature that lets extra hidden data be attached to a file, e.g. file.txt:hidden.exe. Attackers use ADS to hide payloads.", objective: "1.2" },
  { term: "Typosquatting", definition: "Registering domains that resemble legitimate ones through common misspellings, so victims mistype or misread them.", objective: "1.2" },
  { term: "Punycode", definition: "An encoding that represents internationalized domain names in ASCII, starting with xn--. Abused in homoglyph attacks where look-alike characters imitate a real domain.", objective: "1.2" },
  { term: "Business email compromise", definition: "Fraud where an attacker spoofs or hijacks an executive or supplier email account to trick staff into sending money or sensitive data.", objective: "1.2" },
  { term: "Web shell", definition: "A malicious script uploaded to a web server that gives an attacker remote command execution through HTTP requests.", objective: "1.2" },
  { term: "Impossible travel", definition: "Detection of logons to one account from locations too far apart to reach in the time between them, indicating likely credential compromise.", objective: "1.2" },
  { term: "CloudTrail", definition: "AWS service that records account activity as API events (who called what, when and from where). A StopLogging or DeleteTrail event is a strong sign of defense evasion.", objective: "1.2" },
  { term: "Cloud access key", definition: "A long-term credential (an access key ID and secret) used to call a cloud provider's APIs. A new key created from an unfamiliar IP, or a key used from unusual locations, suggests compromise and persistence.", objective: "1.2" },
  { term: "Public storage bucket", definition: "A cloud object storage container whose policy or ACL allows anonymous or all-users access. Often a misconfiguration and sometimes a deliberate step by an attacker to stage data for exfiltration.", objective: "1.2" },
  { term: "MFA fatigue", definition: "An attack where someone with a stolen password sends repeated MFA push requests until the user approves one out of annoyance or confusion. Also called push bombing. Countered by number matching and phishing-resistant MFA.", objective: "1.2" },
  { term: "Session token theft", definition: "Stealing a valid session cookie or token (for example with an infostealer or adversary-in-the-middle phishing) and replaying it from another device, which bypasses the password and MFA. Responders must revoke sessions, not just reset passwords.", objective: "1.2" },
  { term: "Adversary-in-the-middle (AiTM) phishing", definition: "Phishing through a reverse proxy that relays the real sign-in page, so the attacker captures the password and the session cookie issued after MFA.", objective: "1.2" },
  { term: "Baseline", definition: "A documented picture of normal behavior for a user, host, application or network segment (logon times, data volume, processes, ports, destinations), usually built over 30 to 90 days. Anomaly detection measures deviation from it.", objective: "1.2" },
  { term: "Anomaly-based detection", definition: "Detection that flags deviations from a learned or documented baseline instead of matching known signatures. It can catch novel attacks but produces more false positives, so it needs tuning.", objective: "1.2" },
  { term: "Domain generation algorithm (DGA)", definition: "Malware logic that computes many pseudo-random domain names a day and tries them until one the operator registered resolves. Seen as bursts of random-looking lookups that mostly return NXDOMAIN.", objective: "1.2" },
  { term: "NetFlow", definition: "Flow records exported by routers and switches summarizing each conversation (IPs, ports, protocol, bytes, packets, duration) without payload. Used to baseline traffic and spot volume spikes, beaconing and exfiltration even when traffic is encrypted.", objective: "1.2" },
  { term: "NDR", definition: "Network detection and response: tools such as Darktrace or Vectra AI that model network behavior with machine learning to detect anomalies like lateral movement and C2 that have no signature.", objective: "1.2" },
  { term: "ARP poisoning", definition: "Sending forged ARP replies so a victim maps another host's IP (often the gateway) to the attacker's MAC, enabling on-path interception. Detected by one IP mapped to multiple MACs or a sudden MAC change (e.g. Arpwatch).", objective: "1.2" },
  { term: "Evil twin", definition: "A fake wireless access point that copies a legitimate SSID to lure users and capture credentials or traffic. Unlike a rogue AP, it does not need to be connected to the victim's network.", objective: "1.2" },
  { term: "Rogue access point", definition: "An unauthorized wireless AP connected to the internal network (for example a consumer router in a wall jack), which gives anyone nearby a path around perimeter controls. Found with WIDS, NAC and switch port reviews.", objective: "1.2" },
  { term: "MAC OUI", definition: "The organizationally unique identifier: the first three octets of a MAC address, which identify the manufacturer. Looking it up helps classify unknown devices (B8:27:EB is a Raspberry Pi).", objective: "1.2" },
  { term: "NAC", definition: "Network access control: checks that a device is authorized and compliant (e.g. Cisco ISE, FortiNAC) before granting network access, otherwise blocking it or placing it in a quarantine VLAN.", objective: "1.2" },
  { term: "WIDS", definition: "Wireless intrusion detection system: monitors the RF environment for unauthorized SSIDs and AP MAC addresses, rogue APs and evil twins.", objective: "1.2" },
  { term: "Network enumeration", definition: "Active probing to map hosts, open ports, services, operating systems, users and shares (sweeps, port scans, banner grabbing, LDAP/SMB/SNMP queries). Maps to the ATT&CK Discovery tactic.", objective: "1.2" },
  { term: "Banner grabbing", definition: "Connecting to a service to read the version information it announces (e.g. an SSH or HTTP server banner), used by attackers to pick exploits and by defenders to inventory services.", objective: "1.2" },
  { term: "BloodHound", definition: "A tool that collects Active Directory users, groups, sessions and permissions over LDAP/SMB and graphs privilege paths to Domain Admin. Its collection shows up as high-volume LDAP queries from a workstation.", objective: "1.2" },
  { term: "SNMP community string", definition: "The shared password used by SNMP v1/v2c, sent in cleartext. Defaults such as \"public\" (read) and \"private\" (write) leak device and topology information; SNMPv3 adds authentication and encryption.", objective: "1.2" },
  { term: "Deep packet inspection (DPI)", definition: "Examining packet payloads, not just headers, to confirm which protocol is really in use and to spot attacks, for example custom C2 on port 443 or SSH tunneled over a web port.", objective: "1.2" },
  { term: "Low-and-slow scan", definition: "A scan spread over hours or days so each short time window looks harmless and threshold-based IDS signatures do not fire. Caught by SIEM correlation over long windows, e.g. distinct destination ports per source in 24 hours.", objective: "1.2" },
  { term: "Cryptojacking", definition: "Unauthorized use of someone else's computing resources to mine cryptocurrency. Indicators include sustained high CPU/GPU, unexpected instances in unused cloud regions, mining pool connections and billing spikes.", objective: "1.2" },
  { term: "Sysmon", definition: "Free Sysinternals service that logs detailed Windows telemetry: process creation with command line, hashes and parent (EID 1), network connections (3), file creation (11), registry changes (12-14), WMI activity (19-21) and DNS queries (22).", objective: "1.2" },
  { term: "Process injection", definition: "Running malicious code inside the memory of a legitimate process (DLL injection, reflective loading, hollowing) to evade defenses (ATT&CK T1055). Detected through behavior such as a trusted process making unusual network connections.", objective: "1.2" },
  { term: "Process hollowing", definition: "Starting a legitimate process in a suspended state, replacing its memory with a malicious payload and resuming it, so the name and file on disk look legitimate while the code is not.", objective: "1.2" },
  { term: "Masquerading", definition: "Disguising a malicious file or process as a legitimate one, e.g. svchost.exe running from a user folder. Detected by checking path, parent process, user context and digital signature.", objective: "1.2" },
  { term: "LOLBAS", definition: "Living Off The Land Binaries, Scripts and Libraries: a project cataloguing Windows built-in binaries (certutil, mshta, regsvr32 and others) that attackers can abuse, with the flags that make them dangerous.", objective: "1.2" },
  { term: "GTFOBins", definition: "A curated list of Unix/Linux binaries (bash, python, curl, find and others) that can be abused to bypass restrictions, escalate privileges, transfer files or spawn shells.", objective: "1.2" },
  { term: "certutil", definition: "A Windows certificate utility often abused as a LOLBin to download (certutil -urlcache -split -f <URL>) or decode (-decode) payloads. Process creation with these flags and an external URL is a high-fidelity alert.", objective: "1.2" },
  { term: "mshta", definition: "mshta.exe, the Windows host for HTML Applications (.hta). Attackers use it to run script with network access; mshta spawning PowerShell or connecting out is a classic malicious chain.", objective: "1.2" },
  { term: "Squiblydoo", definition: "A technique that abuses regsvr32.exe to download and run a remotely hosted COM scriptlet, bypassing application allowlisting such as AppLocker.", objective: "1.2" },
  { term: "WMI event subscription", definition: "A persistence method that binds a WMI event filter to a consumer so code runs when a condition occurs. It does not appear in Run keys or scheduled tasks; Sysmon EIDs 19, 20 and 21 record it.", objective: "1.2" },
  { term: "File integrity monitoring (FIM)", definition: "Hashing monitored files against a baseline and alerting on any change (e.g. Tripwire, OSSEC/Wazuh). Used to catch tampered system binaries, new startup files and DLL planting.", objective: "1.2" },
  { term: "DLL hijacking", definition: "Placing a malicious DLL where a legitimate program will load it first, usually its own application folder, so trusted signed software runs attacker code. Seen as a new unsigned DLL beside an executable.", objective: "1.2" },
  { term: "Data staging", definition: "Collecting and packaging data before exfiltration, often as password-protected .zip, .7z or .rar archives in Temp, AppData or Desktop created by cmd, PowerShell or script engines.", objective: "1.2" },
  { term: "Event ID 4732", definition: "Windows Security event: a member was added to a security-enabled local group (e.g. the local Administrators group). A common sign of privilege escalation or persistence.", objective: "1.2" },
  { term: "Event ID 4771", definition: "Windows Security event on a domain controller: Kerberos pre-authentication failed. Many across different accounts from one source can indicate password spraying over Kerberos.", objective: "1.2" },
  { term: "Event ID 4776", definition: "Windows Security event: the computer attempted to validate an account's credentials using NTLM. Useful for spotting NTLM-based password guessing and legacy authentication.", objective: "1.2" },
  { term: "Web application firewall (WAF)", definition: "A filter in front of web applications that blocks and logs HTTP attacks such as SQL injection, XSS and path traversal (e.g. AWS WAF, Cloudflare, F5). It is blind if TLS terminates behind it and can be bypassed with encoding.", objective: "1.2" },
  { term: "APM", definition: "Application performance monitoring (e.g. Datadog, New Relic, Dynatrace): tracks response time, throughput, errors and dependencies. Its patterns help separate DDoS or resource exhaustion from targeted injection scans.", objective: "1.2" },
  { term: "Resource exhaustion attack", definition: "A Layer 7 denial of service that sends a moderate number of expensive requests (crafted searches, large reports or uploads) to exhaust CPU, database or connection pools. Moderate traffic with very high backend load is the tell (T1499.003).", objective: "1.2" },
  { term: "Amazon GuardDuty", definition: "AWS threat detection service that analyzes CloudTrail, VPC Flow Logs and DNS logs with machine learning and threat intelligence, producing findings such as CryptoCurrency:EC2/BitcoinTool.B or anomalous IAM behavior.", objective: "1.2" },
  { term: "Amazon Macie", definition: "AWS service that discovers sensitive data (PII, financial data) in S3 and flags risky configurations and anomalous access to it.", objective: "1.2" },
  { term: "AWS Security Hub", definition: "AWS service that aggregates and prioritizes findings from GuardDuty, Macie, Config and other tools, giving analysts a starting point before they dig into CloudTrail.", objective: "1.2" },
  { term: "AWS Config", definition: "AWS service that records resource configuration changes and evaluates them against rules (e.g. s3-bucket-public-read-prohibited), answering \"what changed, and when?\"", objective: "1.2" },
  { term: "Pretexting", definition: "Social engineering that uses an invented scenario and false identity (e.g. a fake help desk technician) to build trust through direct interaction and extract information or actions.", objective: "1.2" },
  { term: "Phishing", definition: "Broad, untargeted deceptive messages, usually email impersonating a known brand, that try to make the recipient click a link, open an attachment or enter credentials (ATT&CK T1566).", objective: "1.2" },
  { term: "Spear phishing", definition: "Phishing researched and tailored to a specific person or organization, using real names, projects and processes. A common initial access method for advanced threat actors.", objective: "1.2" },
  { term: "Whaling", definition: "Spear phishing aimed at senior executives, often to authorize payments or reveal sensitive information.", objective: "1.2" },
  { term: "Vishing", definition: "Voice phishing: social engineering by phone, often impersonating IT, a bank or an executive, sometimes with AI-cloned voices. It bypasses email security controls.", objective: "1.2" },
  { term: "Smishing", definition: "SMS phishing: deceptive text messages with links or callback numbers, impersonating banks, carriers, tax agencies or IT.", objective: "1.2" },
  { term: "Baiting", definition: "Social engineering that exploits curiosity or greed with a lure, such as an infected USB drive labeled \"salary review\" or a fake free download.", objective: "1.2" },
  { term: "Tailgating", definition: "Physical social engineering in which an unauthorized person follows an authorized one through a secured door.", objective: "1.2" },
  { term: "Homograph attack", definition: "Using look-alike characters from other alphabets (e.g. Cyrillic \"а\" for Latin \"a\") in an internationalized domain name so it appears identical to a real domain. Such names appear as punycode beginning with xn--.", objective: "1.2" },
  { term: "Open redirect", definition: "A flaw in a legitimate site that forwards visitors to any URL in a parameter (e.g. /redirect?url=), letting phishers use a trusted domain in links to send victims to a malicious page.", objective: "1.2" },
  { term: "dnstwist", definition: "A tool that generates domain permutations (typos, homoglyphs, added words, other TLDs) and checks which are registered and have MX records, used to hunt lookalike domains.", objective: "1.2" },
  { term: "Certificate transparency", definition: "Public logs of issued TLS certificates, searchable with crt.sh. A certificate just issued for a lookalike domain suggests a phishing campaign is about to start or already live.", objective: "1.2" },
  { term: "urlscan.io", definition: "An online sandbox that visits a URL, follows redirects, screenshots the final page and records connections, so analysts can examine a suspicious link without clicking it.", objective: "1.2" },
  { term: "Display name spoofing", definition: "Setting a trusted person's name as the visible sender (e.g. \"J. Smith, CEO\") on mail from an unrelated address. Common in BEC because it needs no domain registration.", objective: "1.2" },
  { term: "Malicious inbox rule", definition: "A mailbox rule an attacker creates after taking over an account to auto-forward, delete or hide messages (for example moving replies about invoices to an obscure folder). A key BEC and account-compromise indicator.", objective: "1.2" },
  { term: "Credential stuffing", definition: "Replaying username/password pairs leaked from other breaches against a login service at scale, exploiting password reuse. Usually many accounts from many distributed IPs.", objective: "1.2" },
  { term: "Brute-force attack", definition: "Repeatedly guessing passwords for one account (or keys) until one works. Shows as many failed logons for the same account, often followed by lockout or a success.", objective: "1.2" },
  { term: "Initial access broker", definition: "A criminal who breaks into organizations (often with stolen credentials) and sells that access to other groups, such as ransomware operators.", objective: "1.2" },
  { term: "Infostealer", definition: "Malware (e.g. RedLine, Raccoon) that harvests saved browser passwords, cookies and session tokens from an infected device, feeding credential abuse and token replay.", objective: "1.2" },
  { term: "Non-human identity", definition: "A service account, IAM role, managed identity or API key used by software rather than a person. Often highly privileged and poorly monitored, making it an attractive target.", objective: "1.2" },
  { term: "Privilege creep", definition: "The gradual buildup of access rights as users change roles without old permissions being removed. Countered with periodic access reviews and entitlement management.", objective: "1.2" },
  { term: "Pass-the-hash", definition: "Authenticating with a stolen NTLM password hash instead of the password (ATT&CK T1550.002). Often seen as network logons (4624 type 3) moving quickly across hosts.", objective: "1.2" },
  { term: "Pass-the-ticket", definition: "Reusing a stolen Kerberos ticket to authenticate as a user without the password (ATT&CK T1550.003).", objective: "1.2" },

  // 1.3 Use tools to determine malicious activity
  { term: "Wireshark", definition: "Open-source GUI packet analyzer for capturing and inspecting traffic, following streams, and exporting transferred files from captures.", objective: "1.3" },
  { term: "tcpdump", definition: "Command-line packet capture tool for Unix-like systems that uses BPF filters and writes pcap files, e.g. tcpdump -i eth0 port 53.", objective: "1.3" },
  { term: "BPF", definition: "Berkeley Packet Filter: the filter syntax used by tcpdump and Wireshark capture filters to select which packets to record, e.g. host 10.0.0.5 and port 443.", objective: "1.3" },
  { term: "SIEM", definition: "Security Information and Event Management: platform that collects, normalizes, stores and correlates logs from many sources to generate alerts and support investigations.", objective: "1.3" },
  { term: "SOAR", definition: "Security Orchestration, Automation and Response: platform that runs playbooks to automatically enrich, triage and respond to alerts across integrated security tools.", objective: "1.3" },
  { term: "EDR", definition: "Endpoint Detection and Response: agent-based tool that records endpoint telemetry, detects suspicious behavior and lets responders investigate, isolate hosts and kill processes.", objective: "1.3" },
  { term: "XDR", definition: "Extended Detection and Response: correlates detection and response data across endpoints, network, email, identity and cloud in a single platform.", objective: "1.3" },
  { term: "WHOIS", definition: "A protocol and lookup service returning domain registration details such as registrar, creation date and name servers. Very new domains are often suspicious.", objective: "1.3" },
  { term: "AbuseIPDB", definition: "Community database where users report abusive IP addresses. Returns an abuse confidence score and categories like brute force or port scanning.", objective: "1.3" },
  { term: "VirusTotal", definition: "Online service that checks files, hashes, URLs and domains against many antivirus engines and reputation sources. Uploaded files are shared with other users.", objective: "1.3" },
  { term: "strings", definition: "Utility that extracts readable character sequences from a binary file, exposing embedded URLs, IP addresses, commands and file paths.", objective: "1.3" },
  { term: "Sandbox", definition: "An isolated, instrumented environment where suspicious files or URLs are executed to observe their behavior safely.", objective: "1.3" },
  { term: "Cuckoo Sandbox", definition: "Open-source automated malware analysis system that runs samples in isolated VMs and reports processes, file and registry changes and network activity.", objective: "1.3" },
  { term: "Joe Sandbox", definition: "Commercial malware analysis sandbox, offered in the cloud or on-premises, that produces detailed behavior reports for many file types and operating systems.", objective: "1.3" },
  { term: "SPF", definition: "Sender Policy Framework: a DNS TXT record listing the mail servers authorized to send email for a domain, checked against the envelope sender.", objective: "1.3" },
  { term: "DKIM", definition: "DomainKeys Identified Mail: the sending server digitally signs messages, and receivers verify the signature with a public key published in DNS, proving the message is intact and from the signing domain.", objective: "1.3" },
  { term: "DMARC", definition: "Domain-based Message Authentication, Reporting and Conformance: DNS policy that tells receivers how to handle mail failing SPF and DKIM alignment with the From domain (none, quarantine or reject) and where to send reports.", objective: "1.3" },
  { term: "UEBA", definition: "User and Entity Behavior Analytics: builds baselines of normal behavior for users and devices and flags deviations that may indicate compromise or insider threat.", objective: "1.3" },
  { term: "Regular expression", definition: "A pattern language for matching text, used to search logs and write detection rules, e.g. \\d{3}-\\d{2}-\\d{4} for an SSN format.", objective: "1.3" },
  { term: "LOLBin", definition: "Living-off-the-land binary: a legitimate, signed system tool such as certutil, mshta or rundll32 that attackers abuse to evade detection.", objective: "1.3" },
  { term: "Fuzzy hashing", definition: "Hashing that produces similar values for similar files (e.g. ssdeep), helping identify variants of known malware that a normal hash would miss.", objective: "1.3" },
  { term: "TIP", definition: "Threat Intelligence Platform: aggregates, normalizes, deduplicates and scores threat feeds and distributes indicators to security tools.", objective: "1.3" },
  { term: "Zeek", definition: "Open-source network security monitor (formerly Bro) that turns traffic into structured logs such as conn.log, dns.log, http.log and ssl.log, and supports custom detection scripts.", objective: "1.3" },
  { term: "Suricata", definition: "Open-source, multithreaded IDS/IPS and network security monitoring engine that uses signature rules, detects application protocols on any port, and can log protocol metadata and extract files.", objective: "1.3" },
  { term: "Snort", definition: "Open-source signature-based intrusion detection and prevention system. Rules specify an action (such as alert or drop), protocol, addresses, ports and match options; blocking requires inline deployment.", objective: "1.3" },
  { term: "YARA", definition: "A pattern-matching tool and rule language for identifying and classifying malware by text strings, byte sequences and conditions, used to scan files, memory and repositories.", objective: "1.3" },
  { term: "CyberChef", definition: "A browser-based tool for chaining data operations into recipes: encoding and decoding (Base64, hex, URL), decompression, XOR, hashing, timestamp conversion and data extraction.", objective: "1.3" },
  { term: "OpenUBA", definition: "Free, open-source user and entity behavior analytics platform that baselines each entity and accumulates risk scores from anomalies, giving UEBA without commercial SIEM add-on licensing. Needs a few weeks of baselining before alerting.", objective: "1.3" },
  { term: "OTX (Open Threat Exchange)", definition: "AlienVault's free, community-driven threat intelligence platform where anyone can publish and subscribe to pulses of indicators. Quality varies, so check the author and how recently a pulse was updated.", objective: "1.3" },
  { term: "Pulse (OTX)", definition: "The core unit of OTX: a packaged threat report with description, indicators (IPs, domains, URLs, hashes, CVEs, YARA rules), tags, ATT&CK references and timestamps.", objective: "1.3" },
  { term: "MISP", definition: "Malware Information Sharing Platform: open-source TIP for controlled, two-way indicator sharing within trusted communities, organized as events, attributes and objects with distribution levels and TLP tags.", objective: "1.3" },
  { term: "MISP warning list", definition: "A MISP list of known-good infrastructure (such as public DNS resolvers or major cloud ranges) that flags attributes likely to cause false-positive blocks if pushed to security tools.", objective: "1.3" },
  { term: "OpenCTI", definition: "Open-source threat intelligence platform built on a STIX 2.1 knowledge graph that links actors, intrusion sets, campaigns, malware, techniques and indicators, with connectors to MISP, OTX, VirusTotal and ATT&CK.", objective: "1.3" },
  { term: "Observable", definition: "A raw data point seen in the environment, such as an IP, hash or domain, that has not yet been judged malicious. Once evaluated and judged malicious with reasoning, it becomes an indicator.", objective: "1.3" },
  { term: "Intrusion set", definition: "A STIX/OpenCTI object grouping activity and resources believed to come from one operation or adversary that has not yet been attributed to a named threat actor.", objective: "1.3" },
  { term: "MXToolbox", definition: "Free web toolkit for email and DNS investigation: MX, SPF, DKIM and DMARC lookups, blocklist checks and an email header analyzer that shows the route, authentication results and hop delays.", objective: "1.3" },
  { term: "GeoIP", definition: "Mapping an IP address to an approximate country, region and city using registry and commercial data (e.g. MaxMind GeoLite2, ipinfo). Useful context for impossible travel, but VPNs, proxies and Tor make it unreliable for attribution.", objective: "1.3" },
  { term: "Abuse Confidence Score", definition: "AbuseIPDB's 0-100 rating of how likely an IP is to be abusive, based on community reports. Above 80 is a strong malicious indicator, but a low score does not mean safe.", objective: "1.3" },
  { term: "MTD", definition: "Mobile threat defense: security software on mobile devices that actively detects malicious apps, network attacks and OS exploits (e.g. Lookout, Zimperium). MDM manages compliance; MTD detects threats.", objective: "1.3" },
  { term: "Open XDR", definition: "XDR that ingests and correlates telemetry from multiple vendors' tools, as opposed to native XDR, which correlates data only from one vendor's own stack (e.g. Microsoft Defender XDR).", objective: "1.3" },
  { term: "EVE JSON", definition: "Suricata's Extensible Event Format output: structured JSON records for alerts, flows, DNS, HTTP, TLS and file events, with fields such as event_type, src_ip, alert.signature and alert.severity (1 = highest).", objective: "1.3" },
  { term: "Emerging Threats (ET) rules", definition: "Free open IDS/IPS ruleset maintained by Proofpoint and updated daily for Snort and Suricata. Rule names start with ET, as in ET MALWARE or ET SCAN.", objective: "1.3" },
  { term: "zeek-cut", definition: "Zeek utility that extracts named columns from its tab-separated logs, e.g. zeek-cut id.orig_h id.resp_h id.resp_p duration < conn.log, for sorting and counting in a shell.", objective: "1.3" },
  { term: "Display filter", definition: "Wireshark filter applied to already captured packets to choose what is shown (e.g. http.request.method == \"POST\"). Unlike a BPF capture filter, it never discards data.", objective: "1.3" },
  { term: "Follow TCP Stream", definition: "Wireshark feature that reassembles a full TCP conversation in order, showing client and server data in different colors to reveal commands, credentials or exfiltrated content.", objective: "1.3" },
  { term: "Export Objects", definition: "Wireshark feature (File > Export Objects) that extracts files transferred over protocols such as HTTP, SMB or FTP from a capture so they can be hashed and analyzed.", objective: "1.3" },
  { term: "Magic bytes", definition: "Signature bytes at the start of a file that identify its real type regardless of extension, e.g. 4D 5A (\"MZ\") for a Windows executable and 25 50 44 46 (\"%PDF\") for a PDF.", objective: "1.3" },
  { term: "File entropy", definition: "A 0-8 measure of how random a file's bytes are. Values above about 7 suggest packing or encryption, meaning static analysis such as strings will reveal little.", objective: "1.3" },
  { term: "Packer", definition: "A tool that compresses or encrypts an executable and unpacks it at runtime. Malware uses packers to hide strings and evade signatures, which shows up as high entropy.", objective: "1.3" },
  { term: "Imphash", definition: "A hash of a PE file's import table. Variants of the same malware built from the same code often share an imphash even when their file hashes differ.", objective: "1.3" },
  { term: "Static analysis (malware)", definition: "Examining a file without running it: hashes, file type, entropy, strings, headers and YARA matches. Faster and safer than dynamic analysis, so it comes first.", objective: "1.3" },
  { term: "Dynamic analysis (malware)", definition: "Running a sample in an isolated, instrumented environment such as a sandbox to observe its processes, file and registry changes and network activity.", objective: "1.3" },
  { term: "CAPE Sandbox", definition: "Configuration And Payload Extraction: open-source, self-hosted malware sandbox that is the maintained successor to Cuckoo, adding payload and configuration extraction.", objective: "1.3" },
  { term: "INetSim", definition: "Tool that simulates internet services such as DNS, HTTP and SMTP inside an isolated malware lab, so samples get fake responses and their C2 attempts can be captured safely.", objective: "1.3" },
  { term: "Sandbox evasion", definition: "Techniques malware uses to avoid revealing behavior in analysis environments, such as long sleeps, VM artifact checks, user-activity checks or locale checks. A clean sandbox report is not proof of safety.", objective: "1.3" },
  { term: "Normalization (SIEM)", definition: "Mapping fields from different log formats to a common schema (e.g. every source IP into one field) so correlation rules work across vendors. The first thing to check when a rule misses events.", objective: "1.3" },
  { term: "Correlation rule", definition: "SIEM logic combining a data source, condition, time window and action to link related events. Types include threshold, aggregation and sequence rules.", objective: "1.3" },
  { term: "SPL", definition: "Search Processing Language: Splunk's pipe-based query language, e.g. index=windows EventCode=4625 | stats count by src_ip.", objective: "1.3" },
  { term: "KQL", definition: "Kusto Query Language used by Microsoft Sentinel and Defender, e.g. SecurityEvent | where EventID == 4625 | summarize count() by IpAddress. Kibana also has its own query language abbreviated KQL.", objective: "1.3" },
  { term: "Peer group analysis", definition: "UEBA technique that compares a user's behavior with others in the same role or department, flagging access that nobody in the peer group normally has.", objective: "1.3" },
  { term: "Grok pattern", definition: "Named regex building blocks used by Logstash and Elastic to parse unstructured log lines, such as Apache combined logs, into fields like client IP, method, URL and status.", objective: "1.3" },
  { term: "EVTX", definition: "The binary Windows event log file format that stores XML event records, kept in C:\\Windows\\System32\\winevt\\Logs (Security.evtx, System.evtx, Application.evtx).", objective: "1.3" },
  { term: "Script block logging", definition: "PowerShell logging that records the code actually executed, including decoded -EncodedCommand payloads, as Event ID 4104 in the Microsoft-Windows-PowerShell/Operational log.", objective: "1.3" },
  { term: "AMSI", definition: "Antimalware Scan Interface: Windows interface that lets security products scan script content such as PowerShell at runtime. Attackers try to patch it in memory, leaving strings like amsiInitFailed.", objective: "1.3" },
  { term: "PowerShell -EncodedCommand", definition: "PowerShell parameter (-enc, -e) that accepts a Base64-encoded UTF-16LE command. Common in attacks to hide payloads; decode it with CyberChef before judging it.", objective: "1.3" },
  { term: "Fileless malware", definition: "Malicious code that runs in memory through trusted tools such as PowerShell or WMI without writing a traditional executable to disk. Detected with EDR behavior analytics, script logging and memory scanning.", objective: "1.3" },
  { term: "JSON", definition: "JavaScript Object Notation: key/value objects in braces and arrays in brackets. The common format for APIs, cloud logs (CloudTrail), Suricata EVE output and threat intelligence feeds.", objective: "1.3" },
  { term: "XML", definition: "Extensible Markup Language: tag-based format with opening and closing tags and attributes, used by exported Windows events, SAML, Nmap -oX output and older tools.", objective: "1.3" },
  { term: "YAML", definition: "Indentation-based key: value format used for configuration files, Kubernetes, Ansible and detection rules such as Sigma. Whitespace is syntax, so a bad indent can silently break a rule.", objective: "1.3" },
  { term: "awk", definition: "Linux text-processing tool that splits lines into fields and applies logic and math, e.g. awk '{print $11}' to pull a field. Use it over cut when you need counting, sums or conditions.", objective: "1.3" },

  // 1.4 Explain threat intelligence and threat-hunting concepts
  { term: "APT", definition: "Advanced Persistent Threat: a well-resourced, usually state-linked group that maintains long-term covert access to targets for espionage or sabotage.", objective: "1.4" },
  { term: "Hacktivist", definition: "Attacker motivated by political or social causes, typically using defacement, DDoS or data leaks to publicize a message.", objective: "1.4" },
  { term: "Script kiddie", definition: "Low-skill attacker who relies on tools and exploits written by others, usually opportunistic and noisy.", objective: "1.4" },
  { term: "Insider threat", definition: "Risk from people with legitimate access, such as employees or contractors, who cause harm intentionally (theft, sabotage) or unintentionally (mistakes, falling for phishing).", objective: "1.4" },
  { term: "Supply chain attack", definition: "Compromising a vendor, software update, library or service provider in order to reach that supplier's customers.", objective: "1.4" },
  { term: "TTP", definition: "Tactics, Techniques and Procedures: the behavior patterns of a threat actor, from goals (tactics) to methods (techniques) to specific implementations (procedures).", objective: "1.4" },
  { term: "IoC", definition: "Indicator of Compromise: forensic evidence that a system has been breached, such as a malicious hash, IP address, domain or registry key.", objective: "1.4" },
  { term: "IoA", definition: "Indicator of Attack: evidence of attacker behavior or intent in progress, such as a process attempting to read LSASS memory, enabling earlier detection than IoCs.", objective: "1.4" },
  { term: "OSINT", definition: "Open-Source Intelligence: information gathered from publicly available sources like social media, websites, public records and news.", objective: "1.4" },
  { term: "ISAC", definition: "Information Sharing and Analysis Center: sector-based organization where members share threat intelligence, e.g. FS-ISAC for financial services.", objective: "1.4" },
  { term: "CERT", definition: "Computer Emergency Response Team: a group that handles security incidents and publishes advisories, at national, sector or organizational level.", objective: "1.4" },
  { term: "STIX", definition: "Structured Threat Information Expression: a standardized JSON format for describing threat intelligence such as indicators, threat actors and campaigns.", objective: "1.4" },
  { term: "TAXII", definition: "Trusted Automated Exchange of Intelligence Information: a protocol for sharing STIX threat intelligence between systems over HTTPS.", objective: "1.4" },
  { term: "TLP", definition: "Traffic Light Protocol (TLP 2.0): sharing labels CLEAR, GREEN, AMBER, AMBER+STRICT and RED that tell recipients how widely they may pass on a piece of information.", objective: "1.4" },
  { term: "Pyramid of Pain", definition: "Model ranking indicators by how hard they are for attackers to change: hashes, IPs, domains, network/host artifacts, tools, then TTPs at the top.", objective: "1.4" },
  { term: "Threat hunting", definition: "Proactive, hypothesis-driven searching for threats that have evaded automated detection, assuming a compromise may already exist.", objective: "1.4" },
  { term: "Honeypot", definition: "A decoy system with no legitimate use, deployed to attract attackers. Any interaction is suspicious, giving high-fidelity alerts and intelligence on TTPs.", objective: "1.4" },
  { term: "Honeytoken", definition: "Fake data such as a bogus credential, API key or document that triggers an alert when accessed or used.", objective: "1.4" },
  { term: "Active defense", definition: "Defensive actions that engage adversaries inside your own environment, such as deception and honeypots, to detect and study them. Does not include hacking back.", objective: "1.4" },
  { term: "Sinkhole", definition: "Redirecting known malicious domains to a controlled server so infected hosts cannot reach real C2 and can be identified.", objective: "1.4" },
  { term: "STRIDE", definition: "Microsoft threat classification model: Spoofing, Tampering, Repudiation, Information disclosure, Denial of service, Elevation of privilege.", objective: "1.4" },
  { term: "TLP:CLEAR", definition: "TLP 2.0 label meaning disclosure is not limited and the information may be shared publicly. It replaced TLP:WHITE.", objective: "1.4" },
  { term: "TLP:AMBER+STRICT", definition: "TLP 2.0 label added in 2022 that restricts sharing to the recipient's own organization only. Plain TLP:AMBER also allows sharing with the organization's clients on a need-to-know basis.", objective: "1.4" },
  { term: "TAXII collection", definition: "A logical grouping of STIX objects hosted on a TAXII server that clients can read from (poll) or add to, used to organize shared threat intelligence.", objective: "1.4" },
  { term: "STIX indicator pattern", definition: "The detection logic inside a STIX Indicator object, written in the STIX patterning language, e.g. [ipv4-addr:value = '198.51.100.23'] or [file:hashes.'SHA-256' = '...'].", objective: "1.4" },
  { term: "Attack tree", definition: "A threat modeling diagram with the attacker's goal at the root and alternative ways of achieving it as branches and leaves, used to find likely paths and the controls that block them.", objective: "1.4" },
  { term: "Hypothesis-driven hunting", definition: "Threat hunting that starts with a testable statement about attacker behavior (often from threat intel or ATT&CK), identifies the data needed and searches it to prove or disprove the hypothesis.", objective: "1.4" },
  { term: "Threat intelligence lifecycle", definition: "The six-phase cycle for producing intelligence: Direction (requirements), Collection, Processing, Analysis, Dissemination and Feedback. Feedback on usefulness and timeliness sets the next cycle's requirements.", objective: "1.4" },
  { term: "Strategic intelligence", definition: "High-level intelligence about which actors target an industry, their motivations and long-term trends, used by executives for risk and investment decisions.", objective: "1.4" },
  { term: "Operational intelligence", definition: "Intelligence about active or imminent campaigns against organizations like yours and the adversary's likely next moves, used by incident response and threat hunting teams.", objective: "1.4" },
  { term: "Tactical intelligence", definition: "Intelligence describing adversary TTPs (how they move, which tools they use, how they persist), usually expressed with MITRE ATT&CK and used by analysts and detection engineers.", objective: "1.4" },
  { term: "Technical intelligence", definition: "Specific, machine-consumable indicators such as IPs, domains, hashes and email headers that feed SIEM, EDR and firewall rules. Most feeds are technical intel, and it has a short shelf life.", objective: "1.4" },
  { term: "Nation-state actor", definition: "Government-sponsored attacker pursuing espionage, infrastructure disruption or political influence, with large resources, custom malware, zero-days and long dwell times.", objective: "1.4" },
  { term: "Organized crime (threat actor)", definition: "Financially motivated groups running ransomware, BEC, banking trojans and credential theft as a business, often with affiliate models. They respond to cost-benefit, so resilient backups reduce their payoff.", objective: "1.4" },
  { term: "Atomic indicator", definition: "A single, discrete artifact such as an IP, domain, URL, hash, email address, registry key or mutex. Easy to share and block automatically but easy for attackers to change.", objective: "1.4" },
  { term: "Behavioral indicator", definition: "A pattern or sequence of activity (a TTP), such as Office spawning cmd.exe then PowerShell then a download. Harder for attackers to change, so it sits high on the Pyramid of Pain.", objective: "1.4" },
  { term: "Confidence level (threat intelligence)", definition: "How far an analyst can trust and act on intelligence, assessed by timeliness, relevance and accuracy together. High confidence justifies detections and blocking; low confidence is filed until corroborated.", objective: "1.4" },
  { term: "Closed-source intelligence", definition: "Proprietary or restricted intelligence from paid subscriptions, vetted sharing groups or internal telemetry. Often the most timely and detailed because private IR and law enforcement findings never go public.", objective: "1.4" },
  { term: "Dark web monitoring", definition: "Watching criminal forums, marketplaces and paste sites for leaked credentials, stolen data or access for sale that mention your organization. Classed as OSINT because the content is publicly reachable with the right tools.", objective: "1.4" },
  { term: "CISA AIS", definition: "Automated Indicator Sharing: a free US government program that exchanges machine-readable cyber threat indicators (via STIX/TAXII) between government and participating organizations.", objective: "1.4" },
  { term: "Shodan", definition: "A search engine for internet-connected devices and services. Analysts use it to see what is exposed on their own ranges (RDP, management interfaces, outdated servers) or running on a suspicious IP.", objective: "1.4" },
  { term: "crt.sh", definition: "A search interface for Certificate Transparency logs. Reveals certificates issued for a domain, exposing subdomains, shadow IT and new attacker infrastructure such as lookalike phishing sites.", objective: "1.4" },
  { term: "Passive DNS", definition: "Historical records of which domains resolved to which IPs over time (e.g. SecurityTrails, PassiveTotal), used to pivot from one indicator to related infrastructure.", objective: "1.4" },
  { term: "TLP:RED", definition: "TLP 2.0 label restricting information to the named recipients only (for example, those present in a meeting). It may be acted on but not shared further.", objective: "1.4" },
  { term: "TLP:AMBER", definition: "TLP 2.0 label allowing sharing within the recipient's organization and with its clients on a need-to-know basis to protect themselves.", objective: "1.4" },
  { term: "TLP:GREEN", definition: "TLP 2.0 label allowing sharing with the wider security community, such as peers and partner organizations, but not through public channels.", objective: "1.4" },
  { term: "Sub-technique", definition: "In MITRE ATT&CK, a more specific variant of a technique, such as T1059.001 PowerShell under T1059 Command and Scripting Interpreter. Sub-techniques set how precise a detection can be.", objective: "1.4" },
  { term: "ATT&CK Navigator", definition: "A MITRE web tool for creating color-coded layers on the ATT&CK matrix, used to overlay an actor's techniques on your detection coverage and reveal gaps.", objective: "1.4" },
  { term: "Threat heat map", definition: "A visualization that uses color intensity across the ATT&CK matrix to show technique frequency, severity or detection coverage. High actor frequency with no coverage marks the top-priority gap.", objective: "1.4" },
  { term: "Threat mapping", definition: "Aligning the specific techniques of relevant threat actors with your controls, rating each detected, partial or none, to prioritize detection engineering.", objective: "1.4" },
  { term: "Threat attribution", definition: "Identifying who is behind an attack using technical evidence (code traits, infrastructure, timing, TTPs) and strategic context (motive, means, opportunity), always stated with a confidence level.", objective: "1.4" },
  { term: "False flag", definition: "Evidence deliberately planted, such as code or tooling borrowed from another group, to mislead investigators about who conducted an attack.", objective: "1.4" },
  { term: "Intelligence-driven hunting", definition: "Threat hunting that starts from a specific adversary TTP reported in threat intelligence, e.g. searching PowerShell script block logs after a report on T1059.001 abuse.", objective: "1.4" },
  { term: "Baseline-deviation hunting", definition: "Threat hunting that starts from what normal looks like and searches for statistical anomalies, often with ML or UEBA tools.", objective: "1.4" },
  { term: "Stacking", definition: "A hunting analysis technique that counts how often each value (process, task name, service, path) appears across many hosts or records and investigates the rare outliers.", objective: "1.4" },
  { term: "Low-interaction honeypot", definition: "A decoy that emulates a few services or protocols. Easy and low risk to run, but it captures little beyond the initial probe.", objective: "1.4" },
  { term: "High-interaction honeypot", definition: "A decoy running a real OS and services that attackers can use, yielding rich TTP intelligence but carrying pivot risk, so it must be isolated from production.", objective: "1.4" },
  { term: "Honeynet", definition: "A network of honeypots that imitates an enterprise (fake domain controller, workstations, file servers), more convincing to attackers than a single decoy.", objective: "1.4" },
  { term: "Threat-informed defense", definition: "Shaping detections and controls around the real, current TTPs of adversaries relevant to your sector, using MITRE ATT&CK as the backbone, rather than generic best practice.", objective: "1.4" },
  { term: "Data flow diagram (DFD)", definition: "A diagram of how data moves between processes, data stores and external entities across trust boundaries, used in threat modeling to decide where each STRIDE threat applies.", objective: "1.4" },
  { term: "Indicator expiration", definition: "Retiring threat indicators after their validity period (IPs and domains often within 30 to 90 days) so stale entries stop causing false positives in the SIEM and block lists.", objective: "1.4" },

  // 1.5 Describe efficiency and process improvement in security operations
  { term: "Playbook", definition: "A documented, step-by-step procedure for responding to a specific type of security event, with a trigger, triage steps, decision branches, escalation criteria, containment actions and documentation requirements. Its automated form is often called a runbook.", objective: "1.5" },
  { term: "Runbook", definition: "A playbook with automation built in, usually executed by a SOAR through API integrations, that runs the predictable steps and pauses only at human decision points. Many teams use the term interchangeably with playbook.", objective: "1.5" },
  { term: "Orchestration", definition: "Coordinating multiple automated tasks across different security tools into a single end-to-end workflow.", objective: "1.5" },
  { term: "Automation", definition: "Using technology to perform a task without human action, such as automatically blocking a known malicious IP.", objective: "1.5" },
  { term: "Enrichment", definition: "Automatically adding context to alerts or indicators, such as geolocation, WHOIS age, reputation score, asset owner and criticality.", objective: "1.5" },
  { term: "API", definition: "Application Programming Interface: a defined interface that lets programs request data or actions from another system, commonly REST over HTTPS with JSON.", objective: "1.5" },
  { term: "Webhook", definition: "An HTTP callback where a system pushes event data to a configured URL as soon as the event happens, instead of being polled.", objective: "1.5" },
  { term: "Plugin", definition: "A prebuilt add-on or connector that extends a security platform to integrate with a specific product without custom code.", objective: "1.5" },
  { term: "Single pane of glass", definition: "A unified console that brings together data and controls from many security tools so analysts work from one view.", objective: "1.5" },
  { term: "Alert fatigue", definition: "Desensitization caused by large volumes of alerts, many false, leading analysts to miss or ignore real threats.", objective: "1.5" },
  { term: "RACI matrix", definition: "Chart that assigns, for each task, who is Responsible, Accountable, Consulted and Informed, clarifying roles for team coordination.", objective: "1.5" },
  { term: "Approval gate", definition: "A step in an automated workflow that pauses until an authorized person approves the next action. Used before high-impact SOAR actions such as disabling accounts, isolating servers or blocking shared infrastructure.", objective: "1.5" },
  { term: "Alert tuning", definition: "Adjusting detection rules (thresholds, scoping, exclusions, enrichment) so they fire on real threats with less noise. Every change should be documented, tested and reviewed so true positives are not lost.", objective: "1.5" },
  { term: "Suppression rule", definition: "A rule that stops or merges alerts that match known benign conditions or duplicates, such as an authorized scanner. Should be narrowly scoped, documented and periodically reviewed.", objective: "1.5" },
  { term: "Detection engineering", definition: "The practice of designing, testing, deploying and maintaining detection rules as a managed life cycle, often with version control and testing (detection-as-code).", objective: "1.5" },
  { term: "SOC", definition: "Security Operations Center: the centralized team and technology that monitors, detects, analyzes and responds to security threats, typically 24/7.", objective: "1.5" },
  { term: "MSSP", definition: "Managed Security Service Provider: an outside company that monitors and manages an organization's security remotely, often providing a managed SOC.", objective: "1.5" },
  { term: "Hybrid SOC", definition: "A SOC model that mixes in-house staff with an outsourced provider, for example internal Tier 1 and 2 during business hours and MSSP monitoring after hours.", objective: "1.5" },
  { term: "Tier 1 analyst", definition: "SOC triage and monitoring role: works the high-volume alert queue, classifies true or false positives, sets severity, and closes with documentation or escalates.", objective: "1.5" },
  { term: "Tier 2 analyst", definition: "SOC investigation role: correlates multiple sources for confirmed cases, scopes the incident, builds the timeline and looks for lateral movement.", objective: "1.5" },
  { term: "Tier 3 analyst", definition: "SOC hunting and advanced investigation role: runs hypothesis-driven hunts, maps ATT&CK coverage gaps and often writes and tunes detection rules.", objective: "1.5" },
  { term: "Risk-based alerting (RBA)", definition: "An alerting approach that adds risk scores to users and hosts as low-level detections fire and raises a single high-quality alert when an entity's total crosses a threshold, sharply cutting alert volume.", objective: "1.5" },
  { term: "Escalation trigger", definition: "A predefined condition that requires an alert to move to a higher tier or to incident response, such as a critical asset, a privileged account, the same IoCs on multiple systems or ransomware activity.", objective: "1.5" },
  { term: "Case management", definition: "The system of record for an investigation (e.g. ServiceNow, TheHive or a SOAR case) holding every action, artifact, note and decision for traceability, legal support and handover.", objective: "1.5" },
  { term: "TheHive", definition: "An open-source security incident response and case management platform where analysts track cases, tasks and observables such as IoCs.", objective: "1.5" },
  { term: "SOP", definition: "Standard Operating Procedure: a documented, consistent way to perform a task, including steps, tools, decision criteria and escalation thresholds, so every analyst gets the same result.", objective: "1.5" },
  { term: "Shift handoff", definition: "A structured briefing between SOC shifts covering what is automated, what is open, incident status and next actions, so context is not lost.", objective: "1.5" },
  { term: "Configuration drift", definition: "Gradual divergence of a system's actual configuration from its intended baseline through undocumented or manual changes, often leaving insecure settings.", objective: "1.5" },
  { term: "Policy as code", definition: "Security and compliance rules written as code and enforced automatically in deployment pipelines (e.g. HashiCorp Sentinel, AWS Service Control Policies), failing changes that break them.", objective: "1.5" },
  { term: "Shift-left security", definition: "Moving security checks earlier in the development or deployment pipeline, such as scanning IaC templates before deployment, so problems are caught before they reach production.", objective: "1.5" },
  { term: "Checkov", definition: "An open-source static analysis tool that scans Terraform, CloudFormation, Kubernetes manifests and Helm charts for misconfigurations before deployment.", objective: "1.5" },
  { term: "Terraform", definition: "A widely used infrastructure-as-code tool (HashiCorp) that defines cloud and on-prem resources in configuration files and applies them consistently.", objective: "1.5" },
  { term: "CMDB", definition: "Configuration Management Database: the inventory of assets, owners, roles and relationships. A key source of contextual enrichment for judging an alert's business impact.", objective: "1.5" },
  { term: "Contextual enrichment", definition: "Adding internal context to an alert, such as asset owner and criticality (CMDB), user role and department (HR, AD/Entra ID) or known vendor ranges, to judge its true urgency.", objective: "1.5" },
  { term: "API polling", definition: "Repeatedly querying an API on a schedule to check for new data or changes. Simpler than a webhook but slower and wasteful compared with event-driven push.", objective: "1.5" },
  { term: "API status codes (401, 429, 500)", definition: "Common integration errors: 401 = authentication failed (bad or expired API key), 429 = rate limit exceeded, 500 = error on the remote server. SOAR execution logs show them per call.", objective: "1.5" },
  { term: "Cortex XSOAR", definition: "Palo Alto Networks' SOAR platform for orchestrating tools, running automated playbooks and managing cases, with a marketplace of prebuilt integrations.", objective: "1.5" },

  // 1.6 Summarize concepts related to the use of AI in security operations
  { term: "Data poisoning", definition: "Manipulating the data a machine learning model learns from, such as training samples or a UEBA baseline period, so it learns incorrect or attacker-favorable behavior, for example treating malicious activity as normal.", objective: "1.6" },
  { term: "Large language model (LLM)", definition: "A machine learning model trained on very large amounts of text to predict and generate language. In a SOC it can summarize alerts, draft reports and translate questions into queries, but it can also state false information confidently.", objective: "1.6" },
  { term: "Hallucination", definition: "AI output that is fluent and confident but false or unsupported by the input, such as an IP address, hostname or log event that never appeared in the source data. Verify AI claims against the evidence before acting on them.", objective: "1.6" },
  { term: "Prompt injection", definition: "An attack that places instructions in a model's input so it ignores its intended instructions, for example to hide findings, leak data or misuse tools it is connected to.", objective: "1.6" },
  { term: "Direct prompt injection", definition: "Prompt injection typed by the person interacting with the model, such as a user trying to make an assistant reveal its system instructions or bypass its guardrails (often called a jailbreak).", objective: "1.6" },
  { term: "Indirect prompt injection", definition: "Prompt injection hidden in third-party content that an AI later processes, such as an email body, web page, document or log field. The attacker never talks to the model directly.", objective: "1.6" },
  { term: "Model poisoning", definition: "A training-time attack that corrupts what a model learns, by injecting malicious or mislabeled training data or tampering with the model, its fine-tuning or a third-party dataset or model, creating blind spots that persist after deployment.", objective: "1.6" },
  { term: "Model drift", definition: "Gradual loss of a model's accuracy because the data it sees no longer matches the data it was trained on, for example after new applications or work patterns change what normal looks like. Fixed by monitoring performance and retraining.", objective: "1.6" },
  { term: "Over-reliance (automation bias)", definition: "The tendency to accept automated or AI output without enough scrutiny, even when it is wrong or uncertain. Countered with training, evidence requirements and quality sampling of AI-handled work.", objective: "1.6" },
  { term: "AI bias", definition: "Systematic unfairness or error in AI output caused by skewed or unrepresentative training data or design choices, such as flagging one group of users more often for the same behavior.", objective: "1.6" },
  { term: "Human-in-the-loop", definition: "A design in which a person reviews and approves AI recommendations before high-impact actions are taken, keeping accountability with a human decision-maker.", objective: "1.6" },
  { term: "AI acceptable use policy", definition: "A policy defining which AI services staff may use, for what purposes and with which classes of data, along with review, labeling and logging requirements.", objective: "1.6" },
  { term: "AI data leakage", definition: "Exposure of sensitive data through AI use, such as pasting confidential evidence into a third-party model that retains prompts, or a model revealing data from its context to the wrong user.", objective: "1.6" },
  { term: "Output validation (AI)", definition: "Checking AI-generated content (summaries, queries, code, reports) for accuracy and safety before it is used, for example by verifying facts against source logs or testing a generated query against known data.", objective: "1.6" },
  { term: "AI auditability", definition: "Keeping records of the model and version used, inputs, outputs, approvals and resulting actions, so decisions made with AI assistance can be reconstructed and reviewed later.", objective: "1.6" },
  { term: "Deepfake", definition: "Synthetic audio, video or images generated by AI to impersonate a real person. Used in business email compromise and vishing, for example a fake CFO on a video call requesting a wire transfer.", objective: "1.6" },
  { term: "Retrieval-augmented generation (RAG)", definition: "A technique where relevant documents (such as playbooks, past tickets or threat reports) are retrieved and given to a language model with the question, grounding its answers in organizational data. Retrieved content can also carry indirect prompt injection.", objective: "1.6" },
  { term: "AI guardrails", definition: "Controls around an AI system that restrict its inputs, outputs and actions, such as content filters, tool allowlists, rate limits and approval requirements.", objective: "1.6" },
  { term: "Machine learning (ML)", definition: "AI that learns patterns from historical data rather than following fixed rules. In the SOC it powers anomaly detection, malware classification and UEBA.", objective: "1.6" },
  { term: "Supervised learning", definition: "Machine learning trained on labeled examples (e.g. malicious or benign files) to classify new inputs.", objective: "1.6" },
  { term: "Unsupervised learning", definition: "Machine learning that finds structure, clusters or outliers in unlabeled data, well suited to anomaly detection.", objective: "1.6" },
  { term: "Deep learning", definition: "Machine learning using multi-layer neural networks, used for example by EDR products to classify executable behavior in real time instead of relying only on signatures.", objective: "1.6" },
  { term: "ML-based detection", definition: "Detection that learns a baseline of normal behavior and flags deviations, catching novel activity that rules miss. Complements, rather than replaces, rule-based detection.", objective: "1.6" },
  { term: "Adversarial example", definition: "An input crafted to make a deployed ML model misclassify it, such as malware padded with benign-looking features. An inference-time evasion attack, distinct from training-time poisoning.", objective: "1.6" },
  { term: "Model card", definition: "Vendor documentation describing an AI model's intended use, training data, performance and limitations, used to assess the model's risk and transparency.", objective: "1.6" },
  { term: "Model monitoring", definition: "Tracking an AI model's performance metrics (detection rate, false negatives, false positives) over time to spot drift, poisoning or evasion.", objective: "1.6" },
  { term: "NIST AI RMF", definition: "NIST AI Risk Management Framework: voluntary guidance for managing AI risk organized into four functions: Govern, Map, Measure and Manage.", objective: "1.6" },
  { term: "EU AI Act", definition: "EU regulation (in force 2024) that classifies AI systems by risk. High-risk uses require transparency, human oversight and accuracy.", objective: "1.6" },
  { term: "Business Associate Agreement (BAA)", definition: "A HIPAA-required contract with any vendor that handles PHI on a covered entity's behalf. An AI service needs a BAA before PHI is submitted to it.", objective: "1.6" },
  { term: "Data minimization", definition: "A GDPR principle: collect and process only the personal data needed for a specific purpose. Applied to AI, send the tool only what the task requires.", objective: "1.6" },
  { term: "Microsoft Copilot for Security", definition: "Microsoft's LLM-based security assistant that summarizes incidents, drafts reports and helps build queries from Sentinel and Defender data, processing data in the customer tenant.", objective: "1.6" },
  { term: "Sentinel Fusion", definition: "Microsoft Sentinel's ML correlation engine that combines low-fidelity signals from multiple sources into high-confidence, multistage incidents.", objective: "1.6" },
  { term: "AI agent", definition: "An AI model connected to tools (SIEM search, ticketing, EDR actions) so it can act as well as answer. Needs least privilege and approval gates because wrong output becomes wrong action.", objective: "1.6" },
  { term: "AI shared responsibility model", definition: "Division of AI security duties: the vendor builds, secures and updates the model and platform; the customer controls who uses it, what data goes in and how outputs are used.", objective: "1.6" },

  // 2.1 Implement the appropriate vulnerability scanning method
  { term: "Asset discovery", definition: "Identifying all devices, systems and services in an environment, using network sweeps, fingerprinting and inventory sources, so they can be managed and scanned.", objective: "2.1" },
  { term: "Device fingerprinting", definition: "Determining a host's operating system, device type and service versions through banner grabbing, TCP/IP stack behavior or traffic analysis.", objective: "2.1" },
  { term: "Credentialed scan", definition: "A vulnerability scan that logs in to targets to read installed software, patches and configuration, giving more accurate results with fewer false positives.", objective: "2.1" },
  { term: "Non-credentialed scan", definition: "A scan that sees only what is exposed over the network, like an outside attacker. Misses local vulnerabilities and relies more on banners.", objective: "2.1" },
  { term: "Agent-based scanning", definition: "Scanning performed by software installed on each host, which reports results centrally. Works for roaming devices but requires deployment and upkeep.", objective: "2.1" },
  { term: "Agentless scanning", definition: "Scanning performed remotely from a central scanner over the network without installing software on targets.", objective: "2.1" },
  { term: "Passive scanning", definition: "Identifying hosts, services and vulnerabilities by monitoring existing network traffic without sending probes. Safe for fragile systems like ICS.", objective: "2.1" },
  { term: "PCI DSS", definition: "Payment Card Industry Data Security Standard: security requirements for organizations handling payment card data, including quarterly internal and external vulnerability scans.", objective: "2.1" },
  { term: "ASV", definition: "Approved Scanning Vendor: a company qualified by the PCI Security Standards Council to perform the external vulnerability scans PCI DSS requires.", objective: "2.1" },
  { term: "CIS Benchmarks", definition: "Consensus-based secure configuration guides from the Center for Internet Security for operating systems, cloud platforms and applications.", objective: "2.1" },
  { term: "ISO 27001", definition: "International standard specifying requirements for an information security management system (ISMS). Organizations can be certified against it.", objective: "2.1" },
  { term: "SCAP", definition: "Security Content Automation Protocol: NIST suite of standards that lets tools automate configuration checks and vulnerability reporting using common identifiers and formats.", objective: "2.1" },
  { term: "Vulnerability management lifecycle", definition: "The continuous cycle of asset discovery, scanning, analysis and prioritization, remediation, verification and reporting. Skipping a phase, especially verification, breaks the program.", objective: "2.1" },
  { term: "Shadow IT", definition: "Systems, cloud resources or applications deployed without IT or security's knowledge, such as a forgotten test instance. They are unmanaged, unscanned and often unpatched.", objective: "2.1" },
  { term: "Active scanning", definition: "Assessment that sends traffic to targets (port probes, service queries, banner grabs, credentialed logins). Thorough and precise, but it adds load and can disrupt fragile systems.", objective: "2.1" },
  { term: "Internal scan", definition: "A vulnerability scan run from inside the network to show what an insider or an attacker with a foothold could reach, such as domain controllers, databases and backup servers.", objective: "2.1" },
  { term: "External scan", definition: "A vulnerability scan run from outside the perimeter against internet-facing assets to show what an internet attacker can see. Findings are usually the most urgent.", objective: "2.1" },
  { term: "Mapping scan", definition: "A discovery scan that identifies live hosts and open ports, e.g. a ping sweep with nmap -sn followed by a port scan, before deeper assessment.", objective: "2.1" },
  { term: "Baseline scan", definition: "A configuration compliance scan that checks systems against a hardening standard such as CIS Benchmarks or PCI DSS requirements and reports pass or fail per setting, producing a compliance report.", objective: "2.1" },
  { term: "Scan throttling", definition: "Limiting scan intensity (concurrent hosts, checks per host, packet rate) to reduce load on networks and targets, at the cost of longer scan times.", objective: "2.1" },
  { term: "DISA STIG", definition: "Security Technical Implementation Guide: a US Department of Defense hardening baseline for a specific product, used as a configuration standard in baseline scans.", objective: "2.1" },
  { term: "ISO 27002", definition: "The ISO/IEC standard giving implementation guidance for the information security controls listed in ISO 27001 Annex A. It is guidance, not a certification.", objective: "2.1" },
  { term: "HIPAA Security Rule", definition: "US rule requiring covered entities and business associates to protect electronic PHI, including regular technical evaluation. It sets no fixed scan frequency, so scanning is risk-based and documented.", objective: "2.1" },
  { term: "FISMA", definition: "Federal Information Security Modernization Act: requires US federal agencies and contractors to follow NIST SP 800-53 controls and SP 800-137 continuous monitoring, with scan frequency tied to system impact level.", objective: "2.1" },
  { term: "AWS Inspector", definition: "Amazon's managed vulnerability scanner that continuously assesses EC2 instances, Lambda functions and container images, rescanning automatically when new CVE data appears.", objective: "2.1" },
  { term: "Egress filtering", definition: "Controlling outbound traffic, such as allowing DNS only to approved resolvers and web traffic only through the proxy, to block command and control and exfiltration.", objective: "2.1" },
  { term: "Network segmentation", definition: "Dividing a network into zones (physical, VLAN or firewall-based) with controlled traffic between them to limit blast radius and lateral movement. It also limits a scanner's reach, so scanners or agents are needed per segment.", objective: "2.1" },
  { term: "Security group", definition: "A cloud instance-level virtual firewall (e.g. in AWS) that allows specific traffic to a resource. Contrasted with NACLs, which filter at the subnet level.", objective: "2.1" },

  // 2.2 Analyze output from vulnerability assessment tools
  { term: "Fuzzing", definition: "Sending large amounts of malformed or random input to a program to trigger crashes or unexpected behavior that reveals vulnerabilities.", objective: "2.2" },
  { term: "Reverse engineering", definition: "Analyzing compiled software or hardware to understand how it works, using disassemblers, decompilers and debuggers.", objective: "2.2" },
  { term: "Container image scanning", definition: "Checking container images for vulnerable packages, embedded secrets and misconfigurations, typically in the build pipeline and registry, with rescans as new CVEs are published.", objective: "2.2" },
  { term: "CSPM", definition: "Cloud security posture management: tools that continuously assess cloud account configurations through provider APIs against best practices and compliance benchmarks, such as public storage, open security groups or disabled logging.", objective: "2.2" },
  { term: "IaC scanning", definition: "Static analysis of infrastructure-as-code templates (such as Terraform or CloudFormation) to catch misconfigurations before the resources are deployed.", objective: "2.2" },
  { term: "Nmap", definition: "Open-source network scanner used for host discovery, port scanning, service and OS detection, and scripted checks via the Nmap Scripting Engine.", objective: "2.2" },
  { term: "SYN scan", definition: "Nmap -sS half-open scan that sends a SYN, notes the reply, and resets instead of completing the handshake. Faster and less likely to be logged by applications than a full connect scan.", objective: "2.2" },
  { term: "Angry IP Scanner", definition: "Free, fast, cross-platform GUI tool for scanning IP ranges to find live hosts and open ports.", objective: "2.2" },
  { term: "Maltego", definition: "OSINT and link-analysis tool that runs transforms to discover relationships among domains, IPs, people and organizations and displays them as a graph.", objective: "2.2" },
  { term: "Burp Suite", definition: "Web application testing platform built around an intercepting proxy, with tools such as Repeater, Intruder, Decoder and (in Pro) an automated scanner.", objective: "2.2" },
  { term: "ZAP", definition: "Zed Attack Proxy: free, open-source intercepting proxy and web application scanner with spidering, passive and active scanning.", objective: "2.2" },
  { term: "Arachni", definition: "Open-source Ruby-based web application security scanner framework that crawls and audits sites for flaws like XSS and SQL injection.", objective: "2.2" },
  { term: "Nikto", definition: "Open-source command-line web server scanner that checks for dangerous files, outdated software and misconfigurations. Noisy and not stealthy.", objective: "2.2" },
  { term: "Nessus", definition: "Tenable's commercial vulnerability scanner that uses plugins to detect vulnerabilities, missing patches and misconfigurations, with credentialed and compliance scanning.", objective: "2.2" },
  { term: "OpenVAS", definition: "Open-source vulnerability scanner maintained by Greenbone, using network vulnerability tests (NVTs) to assess hosts.", objective: "2.2" },
  { term: "Immunity Debugger", definition: "Windows GUI debugger with a Python API, widely used in exploit development and malware analysis.", objective: "2.2" },
  { term: "GDB", definition: "GNU Debugger: command-line debugger for Linux and Unix programs, used to set breakpoints, step through code and inspect memory and registers.", objective: "2.2" },
  { term: "Metasploit", definition: "Exploitation framework with exploit, payload, auxiliary and post-exploitation modules, used to validate vulnerabilities during authorized testing.", objective: "2.2" },
  { term: "Meterpreter", definition: "An advanced, in-memory Metasploit payload that gives an interactive shell with features like file transfer, process migration and credential collection.", objective: "2.2" },
  { term: "Recon-ng", definition: "Modular, command-line OSINT reconnaissance framework written in Python that stores collected data in a workspace database.", objective: "2.2" },
  { term: "Scout Suite", definition: "Open-source multi-cloud security auditing tool from NCC Group that collects configuration data through provider APIs and reports risky settings.", objective: "2.2" },
  { term: "Prowler", definition: "Open-source cloud security tool, originally for AWS, that checks configurations against best practices and compliance frameworks such as CIS.", objective: "2.2" },
  { term: "Pacu", definition: "Open-source AWS exploitation framework from Rhino Security Labs used by penetration testers to test privilege escalation and other attacks on AWS accounts.", objective: "2.2" },
  { term: "Adversary emulation", definition: "Testing that replicates a specific real threat actor's tactics and techniques to measure how well defenses detect and respond.", objective: "2.2" },
  { term: "Purple teaming", definition: "Red (offensive) and blue (defensive) teams working together, often using ATT&CK, to test and improve detections in real time.", objective: "2.2" },
  { term: "Masscan", definition: "Extremely fast command-line port scanner with its own TCP/IP stack, able to sweep huge address ranges. It reports open ports only and can disrupt networks if its rate is not limited.", objective: "2.2" },
  { term: "Nuclei", definition: "ProjectDiscovery's fast, template-driven vulnerability scanner. Each check is a YAML template with requests and matchers, and community templates often cover new web CVEs quickly.", objective: "2.2" },
  { term: "NSE", definition: "Nmap Scripting Engine: Lua scripts that extend Nmap with categories such as safe, discovery, vuln, brute and exploit, e.g. nmap --script vuln.", objective: "2.2" },
  { term: "TCP connect scan", definition: "Nmap -sT scan that completes the full three-way handshake through the operating system. Works without raw-socket privileges but is noisier and more likely to be logged than a SYN scan.", objective: "2.2" },
  { term: "Filtered port", definition: "An Nmap port state meaning a firewall or filter blocked the probe or no usable reply came back, so Nmap cannot tell whether a service is listening.", objective: "2.2" },
  { term: "Auxiliary module", definition: "A Metasploit module that scans, enumerates or gathers information without exploiting a target, such as SMB version scanners. Often used to validate scanner findings.", objective: "2.2" },
  { term: "Maltego transform", definition: "A query in Maltego that takes one entity (such as a domain) and returns related entities (subdomains, IPs, email addresses), building a link-analysis graph from OSINT sources.", objective: "2.2" },
  { term: "NVT", definition: "Network Vulnerability Test: an individual check in the OpenVAS / Greenbone feed, comparable to a Nessus plugin. Results include a quality of detection (QoD) value.", objective: "2.2" },
  { term: "Intercepting proxy", definition: "A tool that sits between the browser and a web application so the tester can view, modify, replay and fuzz every request and response, as Burp Suite and ZAP do.", objective: "2.2" },
  { term: "Burp Repeater", definition: "Burp Suite tool for manually editing a single captured request and resending it repeatedly to verify a finding.", objective: "2.2" },
  { term: "Burp Intruder", definition: "Burp Suite tool that automatically sends many payload variations to marked positions in a request, used for fuzzing parameters and credential attacks. Throttled in the Community edition.", objective: "2.2" },
  { term: "AJAX Spider", definition: "ZAP crawler that drives a real browser to discover endpoints in JavaScript-heavy applications that a traditional link-following spider misses.", objective: "2.2" },
  { term: "Trivy", definition: "Aqua Security's open-source scanner for container images, filesystems, repositories, Kubernetes and IaC. Image results list CVE, severity, installed version and fixed version; it can also generate SBOMs.", objective: "2.2" },
  { term: "Breach and attack simulation (BAS)", definition: "Automated, continuous and safe execution of ATT&CK-mapped attack techniques to validate whether security controls detect, prevent or miss them.", objective: "2.2" },
  { term: "Atomic Red Team", definition: "Red Canary's free library of small, single-technique tests organized by ATT&CK technique ID, run with Invoke-AtomicTest and including cleanup steps.", objective: "2.2" },
  { term: "MITRE Caldera", definition: "MITRE's open-source adversary emulation platform. A server directs agents (such as Sandcat) to run abilities chained into adversary profiles, including autonomous multi-stage operations.", objective: "2.2" },
  { term: "Red team", definition: "Offensive team that simulates real adversaries across full attack chains, often over weeks and without defenders' prior knowledge, to test detection and response.", objective: "2.2" },
  { term: "Blue team", definition: "Defensive team that detects, analyzes and responds to attacks, and afterwards maps red team techniques to log sources and detections to close gaps.", objective: "2.2" },
  { term: "Greenbone Security Assistant", definition: "The web interface for OpenVAS (Greenbone Community Edition), used to configure targets, run scans and review results.", objective: "2.2" },

  // 2.3 Prioritize and mitigate vulnerabilities
  { term: "False positive", definition: "A result that reports a vulnerability or threat that is not actually present.", objective: "2.3" },
  { term: "False negative", definition: "A failure to report a vulnerability or threat that actually exists. The most dangerous error because it creates false confidence.", objective: "2.3" },
  { term: "True positive", definition: "A correct report of a vulnerability or threat that really exists.", objective: "2.3" },
  { term: "CVSS", definition: "Common Vulnerability Scoring System: open standard that scores vulnerability severity from 0.0 to 10.0 using base, temporal and environmental metrics.", objective: "2.3" },
  { term: "CVE", definition: "Common Vulnerabilities and Exposures: a unique public identifier for a known vulnerability, in the form CVE-year-number.", objective: "2.3" },
  { term: "Attack Vector", definition: "CVSS base metric describing how remote an attacker can be: Network, Adjacent, Local or Physical. Network scores highest.", objective: "2.3" },
  { term: "Attack Complexity", definition: "CVSS base metric rating conditions beyond the attacker's control needed for exploitation: Low or High.", objective: "2.3" },
  { term: "Privileges Required", definition: "CVSS base metric for the level of access an attacker needs before exploiting: None, Low or High.", objective: "2.3" },
  { term: "User Interaction", definition: "CVSS base metric indicating whether a user other than the attacker must take an action: None or Required.", objective: "2.3" },
  { term: "Scope", definition: "CVSS base metric showing whether exploitation affects resources beyond the vulnerable component's security authority: Unchanged or Changed.", objective: "2.3" },
  { term: "Zero-day", definition: "A vulnerability unknown to the vendor or without an available patch, which attackers may already be exploiting.", objective: "2.3" },
  { term: "Weaponization", definition: "Turning a vulnerability into a reliable, packaged exploit or malware that can be used easily, raising the urgency to remediate.", objective: "2.3" },
  { term: "EPSS", definition: "Exploit Prediction Scoring System: data-driven estimate of the probability that a vulnerability will be exploited in the wild in the next 30 days.", objective: "2.3" },
  { term: "KEV catalog", definition: "CISA's Known Exploited Vulnerabilities catalog: list of vulnerabilities confirmed to be actively exploited, used to prioritize patching.", objective: "2.3" },
  { term: "Asset criticality", definition: "How important a system and its data are to the business, used with severity and exploitability to prioritize remediation.", objective: "2.3" },
  { term: "Reflected XSS", definition: "Cross-site scripting where the malicious script is part of the request (usually a link) and is immediately echoed back in the response, affecting the user who clicks it.", objective: "2.3" },
  { term: "Stored XSS", definition: "Persistent cross-site scripting where the malicious script is saved on the server, such as in a comment, and runs for every user who views it.", objective: "2.3" },
  { term: "Buffer overflow", definition: "Writing more data to a memory buffer than it can hold, overwriting adjacent memory and potentially allowing code execution.", objective: "2.3" },
  { term: "Integer overflow", definition: "An arithmetic result exceeds the maximum value of its data type and wraps around, often leading to undersized memory allocations.", objective: "2.3" },
  { term: "ASLR", definition: "Address Space Layout Randomization: randomizes memory locations of code and data so attackers cannot reliably predict addresses for exploits.", objective: "2.3" },
  { term: "DEP", definition: "Data Execution Prevention: marks memory regions such as the stack and heap as non-executable to block injected code from running.", objective: "2.3" },
  { term: "IDOR", definition: "Insecure Direct Object Reference: an access control flaw where changing an identifier, such as an account number in a URL, exposes another user's data.", objective: "2.3" },
  { term: "SQL injection", definition: "Inserting SQL code into input that is built into a database query, letting the attacker read, change or delete data. Prevented by parameterized queries.", objective: "2.3" },
  { term: "Parameterized query", definition: "A query where user input is bound as a parameter instead of concatenated into the SQL text, so the database never executes it as code.", objective: "2.3" },
  { term: "CSRF", definition: "Cross-Site Request Forgery: tricks a logged-in user's browser into sending an unwanted authenticated request. Prevented with anti-CSRF tokens and SameSite cookies.", objective: "2.3" },
  { term: "SSRF", definition: "Server-Side Request Forgery: makes a server send requests to destinations chosen by the attacker, such as internal services or cloud metadata endpoints.", objective: "2.3" },
  { term: "Directory traversal", definition: "Using sequences like ../ in file paths to access files outside the intended directory, such as /etc/passwd.", objective: "2.3" },
  { term: "LFI", definition: "Local File Inclusion: a flaw that lets an attacker make the application include and display or run a file already on the server.", objective: "2.3" },
  { term: "RFI", definition: "Remote File Inclusion: a flaw that lets an attacker make the application include a file from an external URL, usually resulting in code execution.", objective: "2.3" },
  { term: "RCE", definition: "Remote Code Execution: the ability for an attacker to run arbitrary code on a target system over a network.", objective: "2.3" },
  { term: "Privilege escalation", definition: "Gaining higher permissions than granted. Vertical means moving to admin or root; horizontal means accessing another user's resources at the same level.", objective: "2.3" },
  { term: "XXE", definition: "XML External Entity: an injection flaw where a weakly configured XML parser processes external entity references, exposing local files or enabling SSRF.", objective: "2.3" },
  { term: "Content Security Policy", definition: "HTTP response header that restricts where scripts and other resources may load from, reducing the impact of XSS.", objective: "2.3" },
  { term: "Output encoding", definition: "Converting data into a safe form for the context where it is displayed, such as HTML entities, so it is treated as text instead of code.", objective: "2.3" },
  { term: "Input validation", definition: "Checking that input matches expected type, length, format and range, ideally on the server with an allow-list, before it is processed.", objective: "2.3" },
  { term: "EPSS percentile", definition: "The rank of a CVE's EPSS probability compared with all scored CVEs. A percentile of 0.95 means the score is higher than 95 percent of CVEs; it is not itself a probability.", objective: "2.3" },
  { term: "BOD 22-01", definition: "CISA Binding Operational Directive 22-01 (2021), which created the KEV catalog and requires US federal civilian agencies to remediate listed vulnerabilities by set due dates.", objective: "2.3" },
  { term: "Risk-based vulnerability management", definition: "Prioritizing remediation by combining severity with exploit likelihood (KEV, EPSS, threat intel), asset criticality and exposure, rather than working through raw CVSS scores in order.", objective: "2.3" },
  { term: "SSVC", definition: "Stakeholder-Specific Vulnerability Categorization: a decision-tree method, used by CISA, that turns factors such as exploitation status and mission impact into actions (Track, Track*, Attend, Act).", objective: "2.3" },
  { term: "Exploit maturity", definition: "How developed available exploit code is, from none or theoretical to proof-of-concept to reliable, weaponized tools. A CVSS threat metric and a key input to prioritization.", objective: "2.3" },
  { term: "Compensating control", definition: "An alternative safeguard used when the primary control, such as patching, cannot be applied. It makes exploitation harder or limits impact (e.g. isolating an unpatchable system) but does not remove the vulnerability, so it is documented and temporary.", objective: "2.3" },
  { term: "Maintenance window", definition: "A pre-approved time period when changes, patches and reboots can be made with minimal business impact.", objective: "2.3" },
  { term: "Attack surface", definition: "All the points where an attacker could attempt to enter or extract data from an environment, including systems, apps, accounts and people.", objective: "2.3" },
  { term: "Bug bounty", definition: "A program that rewards external researchers for finding and responsibly reporting vulnerabilities in published, usually internet-facing, scope under defined rules.", objective: "2.3" },
  { term: "Rules of engagement", definition: "The agreed scope, timing, methods and limits for a penetration test or security assessment.", objective: "2.3" },
  { term: "True negative", definition: "A correct result showing that a vulnerability or threat is not present. No action is needed beyond the normal scan cadence.", objective: "2.3" },
  { term: "Backporting", definition: "Applying a security fix to an older software version without changing its upstream version number, as Linux distributions do. A common cause of banner-based false positives.", objective: "2.3" },
  { term: "CVSS vector string", definition: "Compact text listing CVSS metric values, e.g. CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:H (9.8). Reading it shows which metrics drive the score.", objective: "2.3" },
  { term: "CVSS temporal metrics", definition: "CVSS v3.1 metrics that change over time: Exploit Code Maturity, Remediation Level and Report Confidence. Renamed threat metrics in CVSS v4.0.", objective: "2.3" },
  { term: "CVSS environmental metrics", definition: "CVSS metrics that adapt a score to an organization through modified base metrics (such as Modified Attack Vector) and confidentiality, integrity and availability requirements.", objective: "2.3" },
  { term: "Remediation", definition: "Fully fixing a vulnerability, for example by patching, correcting a configuration or replacing software, so the flaw no longer exists. Contrast with mitigation, which only reduces risk.", objective: "2.3" },
  { term: "Vulnerability exception", definition: "A formal, approved and time-limited decision to leave a known vulnerability unremediated, documenting the vulnerability, justification, risk assessment, compensating controls, approver and expiry date.", objective: "2.3" },
  { term: "Attack surface management", definition: "Continuously discovering, monitoring and reducing every exposed entry point, using edge and passive discovery, controls testing (pentests, BAS), bug bounties and attack surface reduction.", objective: "2.3" },
  { term: "Edge discovery", definition: "Finding internet-facing assets and exposed services from the outside in, including load balancers, APIs, cloud storage, SaaS and forgotten hosts, with tools such as Shodan, Censys or EASM services.", objective: "2.3" },
  { term: "Passive discovery", definition: "Learning about exposure without sending probes to the target, using certificate transparency logs, passive DNS, WHOIS, search engines and public code repositories.", objective: "2.3" },
  { term: "Attack surface reduction", definition: "Removing or disabling what is not needed (services, ports, apps, accounts, public exposure) and applying least privilege and segmentation to shrink the attack surface.", objective: "2.3" },
  { term: "ASR rules", definition: "Microsoft Defender for Endpoint attack surface reduction rules that block risky behaviors such as Office apps spawning child processes or credential theft from LSASS.", objective: "2.3" },
  { term: "Penetration test", definition: "An authorized, time-boxed attempt to find and exploit weaknesses within an agreed scope and rules of engagement, providing evidence of real risk.", objective: "2.3" },
  { term: "Patch management lifecycle", definition: "Assess (inventory and missing patches), test, schedule, deploy, validate and document, with rollback plans and emergency changes for critical, actively exploited flaws.", objective: "2.3" },
  { term: "Emergency change", definition: "An expedited change-management path for urgent fixes, such as patching an actively exploited critical flaw, that is still documented and reviewed afterwards.", objective: "2.3" },
  { term: "Rollback plan", definition: "A documented, tested procedure for reversing a change (snapshot, backup or uninstall steps) if a patch or configuration change breaks production.", objective: "2.3" },
  { term: "WAF", definition: "Web application firewall: filters HTTP traffic for attack patterns such as SQL injection and XSS. Often used as a compensating control or virtual patch, not a replacement for fixing code.", objective: "2.3" },
  { term: "Virtual patching", definition: "Blocking exploitation of a known flaw with a WAF or IPS rule while the actual fix is pending. It mitigates but does not remediate the vulnerability.", objective: "2.3" },
  { term: "Validation of remediation", definition: "Confirming through a targeted rescan, or by testing a compensating control's protective effect, that a fix or mitigation actually worked, and documenting the result.", objective: "2.3" },
  { term: "NIST SP 800-40", definition: "NIST guide to enterprise patch management planning, covering how organizations prioritize, deploy and track patches and handle exceptions.", objective: "2.3" },

  // 2.4 Explain concepts related to control types, risks and vulnerability management
  { term: "SAST", definition: "Static Application Security Testing: analyzing source code or binaries for security flaws without running the program.", objective: "2.4" },
  { term: "DAST", definition: "Dynamic Application Security Testing: testing a running application from the outside by sending attacks and analyzing responses.", objective: "2.4" },
  { term: "SBOM", definition: "Software Bill of Materials: a machine-readable inventory of every component in a piece of software (libraries, versions, suppliers, licenses), in formats such as CycloneDX or SPDX, used to find affected products quickly when a component flaw is announced.", objective: "2.4" },
  { term: "Software composition analysis (SCA)", definition: "Testing that inventories the third-party and open-source components in an application, including transitive dependencies, and flags known vulnerabilities and license issues.", objective: "2.4" },
  { term: "CycloneDX", definition: "An OWASP SBOM standard, lightweight and security-focused, written in JSON or XML and supported by tools such as Trivy, Snyk and Dependency-Track.", objective: "2.4" },
  { term: "SPDX", definition: "Software Package Data Exchange: a Linux Foundation standard (also ISO/IEC 5962) for SBOMs that records components, versions and licenses.", objective: "2.4" },
  { term: "API security testing", definition: "Testing APIs using their specification (such as OpenAPI) and authenticated sessions to find flaws like broken object-level authorization, excessive data exposure and missing rate limits that link-crawling scanners miss.", objective: "2.4" },
  { term: "Corrective control", definition: "A control that fixes damage or restores systems after an incident, such as restoring from backup or re-imaging.", objective: "2.4" },
  { term: "Preventive control", definition: "A control that stops an incident before it occurs by reducing likelihood, such as a firewall rule, MFA or patching. Also written preventative.", objective: "2.4" },
  { term: "Detective control", definition: "A control that identifies an incident during or after it occurs, such as an IDS, SIEM alert or log review.", objective: "2.4" },
  { term: "Managerial control", definition: "A control focused on people, policy and governance, such as policies, risk assessments and awareness programs. Also called an administrative control.", objective: "2.4" },
  { term: "Operational control", definition: "Control carried out primarily by people as part of daily operations, such as security guards, change management and awareness training.", objective: "2.4" },
  { term: "Risk acceptance", definition: "A documented decision by an authorized owner to tolerate a risk without further action, usually time-limited and reviewed.", objective: "2.4" },
  { term: "Risk transference", definition: "Shifting the financial impact of a risk to another party, for example through cyber insurance or contracts.", objective: "2.4" },
  { term: "Risk avoidance", definition: "Eliminating a risk by stopping the activity that causes it, such as decommissioning a vulnerable service.", objective: "2.4" },
  { term: "Risk mitigation", definition: "Reducing the likelihood or impact of a risk by applying controls such as patches, segmentation or MFA.", objective: "2.4" },
  { term: "Residual risk", definition: "The risk that remains after controls have been applied.", objective: "2.4" },
  { term: "SLO", definition: "Service Level Objective: an internal performance target, such as remediating critical vulnerabilities within a set number of days.", objective: "2.4" },
  { term: "Threat modeling", definition: "Structured process of identifying potential threats to a system design, ranking them and planning mitigations, ideally during design.", objective: "2.4" },
  { term: "SDLC", definition: "Software Development Life Cycle: the phases of building software from planning and requirements through design, coding, testing, deployment and maintenance.", objective: "2.4" },
  { term: "Inherent risk", definition: "The level of risk before any controls are applied, based on the asset, the threat landscape and known vulnerabilities.", objective: "2.4" },
  { term: "Risk appetite", definition: "The overall amount of risk an organization is willing to accept in pursuit of its goals, set by leadership such as the board and executives.", objective: "2.4" },
  { term: "Risk tolerance", definition: "The acceptable variation around the risk appetite for a specific risk or area, the threshold beyond which leadership must step in.", objective: "2.4" },
  { term: "SLE", definition: "Single loss expectancy: the expected cost of one occurrence of a loss event, calculated as asset value × exposure factor.", objective: "2.4" },
  { term: "ARO", definition: "Annualized rate of occurrence: how many times a loss event is expected per year, e.g. 0.2 for once every five years.", objective: "2.4" },
  { term: "ALE", definition: "Annualized loss expectancy: the expected yearly cost of a risk, calculated as SLE × ARO and compared with the annual cost of a control.", objective: "2.4" },
  { term: "Exposure factor", definition: "The percentage of an asset's value expected to be lost in a single incident, used to calculate SLE.", objective: "2.4" },
  { term: "Risk matrix", definition: "A grid (heat map) that plots likelihood against impact so risks can be ranked, from low/low (green) to high/high (red).", objective: "2.4" },
  { term: "NIST RMF", definition: "NIST Risk Management Framework, the US federal process with six steps: Categorize, Select, Implement, Assess, Authorize and Monitor.", objective: "2.4" },
  { term: "ISO 31000", definition: "International guideline for enterprise risk management principles and processes.", objective: "2.4" },
  { term: "Administrative control", definition: "A control focused on people and policy, such as security policies, awareness training, background checks and separation of duties. Also called a managerial control.", objective: "2.4" },
  { term: "Technical control", definition: "A control implemented in technology, such as firewalls, encryption, MFA, EDR, ACLs and SIEM.", objective: "2.4" },
  { term: "Physical control", definition: "A control that protects facilities and hardware, such as locks, badge readers, guards, CCTV, rack cages and fire suppression.", objective: "2.4" },
  { term: "Responsive control", definition: "A control that acts during an active incident to contain damage, such as isolating a host, blocking an IP address or disabling an account.", objective: "2.4" },
  { term: "Defense in depth", definition: "Layering multiple, different controls (administrative, technical and physical; network, host and application) so that one failure does not lead to compromise.", objective: "2.4" },
  { term: "Security policy", definition: "A broad, mandatory statement from leadership of what must be done and why. Supported by standards, procedures and guidelines.", objective: "2.4" },
  { term: "Security standard", definition: "A specific, measurable requirement that supports a policy, such as a minimum password length or an approved encryption algorithm.", objective: "2.4" },
  { term: "Procedure", definition: "Step-by-step instructions describing how to carry out a task, such as isolating an endpoint during an incident.", objective: "2.4" },
  { term: "Guideline", definition: "A recommended practice that is advisory rather than mandatory.", objective: "2.4" },
  { term: "Governance", definition: "The structures, roles and processes that align security with business goals and assign accountability, from the board setting risk appetite to analysts following procedures and escalating.", objective: "2.4" },
  { term: "GRC platform", definition: "Governance, risk and compliance software (e.g. ServiceNow GRC, Archer, OneTrust) used to track risks, control gaps, exceptions, vendor assessments and compliance evidence.", objective: "2.4" },
  { term: "OWASP Top 10", definition: "OWASP's consensus list of the most critical web application security risks, led by broken access control, cryptographic failures and injection in the 2021 edition.", objective: "2.4" },
  { term: "IAST", definition: "Interactive application security testing: instrumentation inside a running application that observes code execution during testing, combining static and dynamic views.", objective: "2.4" },
  { term: "Taint analysis", definition: "A SAST technique that marks user-controlled input as tainted and alerts when it reaches a dangerous sink, such as a SQL query or OS command, without sanitization.", objective: "2.4" },
  { term: "Authenticated DAST", definition: "Dynamic testing performed while logged in as one or more user roles, needed to find broken access control, IDOR and privilege escalation behind the login.", objective: "2.4" },
  { term: "Semgrep", definition: "Open-source, pattern-based SAST tool supporting many languages, commonly run in CI pipelines with community or custom rules.", objective: "2.4" },
  { term: "OWASP SAMM", definition: "Software Assurance Maturity Model: measures an organization's application security maturity across 5 business functions (Governance, Design, Implementation, Verification, Operations) and 15 practices, scored 0 to 3.", objective: "2.4" },
  { term: "Shift left", definition: "Moving security testing earlier in the development life cycle (SAST, SCA and IaC scanning on every commit) where flaws are cheaper to fix.", objective: "2.4" },
  { term: "DevSecOps", definition: "Integrating automated security checks and shared security responsibility into DevOps pipelines so code cannot reach production without passing security gates.", objective: "2.4" },
  { term: "Third-party risk management (TPRM)", definition: "Identifying, assessing, contracting for, monitoring and offboarding the risk that vendors and service providers introduce through access to systems, data or operations.", objective: "2.4" },
  { term: "Fourth party", definition: "A vendor's own supplier or sub-processor. Their weaknesses can reach you indirectly, so TPRM inventories should include them.", objective: "2.4" },
  { term: "SOC 2 Type I", definition: "An audit report on whether a service organization's controls were suitably designed at a single point in time.", objective: "2.4" },
  { term: "SOC 2 Type II", definition: "An audit report on whether a service organization's controls operated effectively over a period, usually 6 to 12 months. More assurance than Type I.", objective: "2.4" },
  { term: "SIG questionnaire", definition: "Shared Assessments Standardized Information Gathering questionnaire: a widely used vendor security questionnaire covering domains such as access control, incident response and data security.", objective: "2.4" },
  { term: "CAIQ", definition: "Consensus Assessments Initiative Questionnaire from the Cloud Security Alliance, used to assess cloud providers and mapped to the Cloud Controls Matrix.", objective: "2.4" },
  { term: "Right to audit", definition: "A contract clause letting the customer audit a vendor's security controls. A vendor refusing a contractually agreed audit is itself a significant risk finding.", objective: "2.4" },
  { term: "Attestation", definition: "A vendor's own assertion or third-party report about its controls (questionnaires, SOC reports). Contrast with validation, where the customer independently confirms controls work.", objective: "2.4" },
  { term: "Transitive dependency", definition: "A library your code uses indirectly because one of your direct dependencies depends on it. SCA must include these, as Log4Shell showed.", objective: "2.4" },
  { term: "Reachability analysis", definition: "SCA analysis that checks whether a vulnerable function in a dependency is actually called by the application, used to prioritize findings.", objective: "2.4" },
  { term: "Dependency confusion", definition: "A supply chain attack in which an attacker publishes a public package with the same name as an internal one, usually with a higher version, so builds pull the malicious copy.", objective: "2.4" },
  { term: "Private artifact repository", definition: "An internal package registry or proxy (e.g. Artifactory, Nexus) that serves only approved component versions, blocks known-vulnerable packages and keeps an audit trail.", objective: "2.4" },
  { term: "VEX", definition: "Vulnerability Exploitability eXchange: a supplier statement saying whether a vulnerable component listed in an SBOM is actually exploitable in its product.", objective: "2.4" },
  { term: "Executive Order 14028", definition: "2021 US executive order on improving the nation's cybersecurity that requires SBOMs for software sold to federal agencies.", objective: "2.4" },
  { term: "NTIA minimum elements", definition: "The baseline SBOM fields: supplier name, component name, version, unique identifier, dependency relationships, SBOM author and timestamp.", objective: "2.4" },
  { term: "OWASP Dependency-Track", definition: "Open-source platform that ingests SBOMs and continuously monitors their components against vulnerability databases, alerting when new CVEs affect them.", objective: "2.4" },
  { term: "Security rating service", definition: "A service such as BitSight or SecurityScorecard that scores an organization's external security posture from outside observations, used for continuous vendor monitoring.", objective: "2.4" },
  { term: "NIST SP 800-161", definition: "NIST guidance on cybersecurity supply chain risk management (C-SCRM) for systems and organizations.", objective: "2.4" },

  // 3.1 Summarize concepts related to attack methodology frameworks
  { term: "Cyber Kill Chain", definition: "Lockheed Martin model of seven intrusion stages: Reconnaissance, Weaponization, Delivery, Exploitation, Installation, Command and Control, Actions on Objectives.", objective: "3.1" },
  { term: "Weaponization stage", definition: "Kill Chain stage where the attacker couples an exploit with a payload to create a deliverable weapon, such as a malicious document.", objective: "3.1" },
  { term: "Actions on Objectives", definition: "Final Kill Chain stage where the attacker achieves the goal, such as data theft, encryption or destruction.", objective: "3.1" },
  { term: "Diamond Model", definition: "Intrusion analysis model that describes each event by four connected vertices: Adversary, Capability, Infrastructure and Victim.", objective: "3.1" },
  { term: "Pivoting (analysis)", definition: "In threat analysis, using one known element, such as a C2 IP address, to discover related elements like other victims or malware.", objective: "3.1" },
  { term: "MITRE ATT&CK", definition: "Knowledge base of real-world adversary tactics and techniques organized as a matrix, used for detection engineering, threat hunting and emulation.", objective: "3.1" },
  { term: "Tactic", definition: "In ATT&CK, the adversary's goal for an action, such as Persistence or Credential Access. Shown as matrix columns with TA IDs.", objective: "3.1" },
  { term: "Technique", definition: "In ATT&CK, how an adversary achieves a tactic, such as Scheduled Task/Job. Identified by T IDs, with sub-techniques like T1059.001.", objective: "3.1" },
  { term: "OSSTMM", definition: "Open Source Security Testing Methodology Manual: ISECOM's peer-reviewed methodology for measurable security testing across human, physical, wireless, telecommunications and data network channels.", objective: "3.1" },
  { term: "OWASP Testing Guide", definition: "OWASP's Web Security Testing Guide: a structured framework of test cases for assessing web application and API security.", objective: "3.1" },
  { term: "Reconnaissance stage", definition: "First Kill Chain stage: researching the target, either passively (OSINT, DNS, social media) or actively (port scans, probes). Active recon can be caught with IDS and network rules.", objective: "3.1" },
  { term: "Delivery stage", definition: "Kill Chain stage where the weapon reaches the target, e.g. phishing email, malicious attachment, drive-by download or USB drop. The first real chance to block the attack.", objective: "3.1" },
  { term: "Exploitation stage", definition: "Kill Chain stage where the payload executes by exploiting a vulnerability or tricking the user. EDR and patching are the main defenses.", objective: "3.1" },
  { term: "Installation stage", definition: "Kill Chain stage where the attacker establishes persistence, such as a scheduled task, Run key, service or web shell, so access survives reboots.", objective: "3.1" },
  { term: "Command and control (C2)", definition: "Communication channel an implant uses to receive attacker instructions, often disguised as HTTPS, DNS or requests to legitimate-looking domains. Also the sixth Kill Chain stage and an ATT&CK tactic.", objective: "3.1" },
  { term: "Extended kill chain", definition: "View of intrusions as non-linear: after initial compromise attackers loop back into internal reconnaissance and lateral movement, often with several footholds, so responders must hunt after each containment.", objective: "3.1" },
  { term: "Adversary (Diamond Model)", definition: "The Diamond Model vertex for who is behind an intrusion: nation-state group, criminal gang, insider or hacktivist. Even partial knowledge, such as financial motivation, guides the response.", objective: "3.1" },
  { term: "Capability (Diamond Model)", definition: "The Diamond Model vertex for what the adversary used: malware, exploits, tools such as Cobalt Strike, or living-off-the-land techniques.", objective: "3.1" },
  { term: "Infrastructure (Diamond Model)", definition: "The Diamond Model vertex for where the attack operates from: C2 servers, domains, IP addresses, hosting and email accounts. Often reused, which makes it a strong pivot point.", objective: "3.1" },
  { term: "Victim (Diamond Model)", definition: "The Diamond Model vertex for the target: the organization, people and assets attacked. Understanding why they were targeted helps predict future targets.", objective: "3.1" },
  { term: "Meta-features (Diamond Model)", definition: "Extra attributes recorded for each Diamond Model event, such as timestamp, kill chain phase, result, direction, methodology, resources and a confidence value for each data point.", objective: "3.1" },
  { term: "Activity thread", definition: "In the Diamond Model, a chain of related events ordered by attack phase. Threads can be grouped to track campaigns and adversaries over time.", objective: "3.1" },
  { term: "Procedure (ATT&CK)", definition: "A specific, documented example of how a threat group implemented a technique, the most concrete level of TTPs in ATT&CK.", objective: "3.1" },
  { term: "D3FEND", definition: "MITRE knowledge base of defensive countermeasures, mapped to the offensive techniques in ATT&CK.", objective: "3.1" },
  { term: "CAPEC", definition: "Common Attack Pattern Enumeration and Classification: MITRE catalog of attack patterns used against software and applications.", objective: "3.1" },
  { term: "Cobalt Strike", definition: "Commercial adversary simulation framework whose beacon payload is widely abused by criminals and APTs. In the Diamond Model it is a capability.", objective: "3.1" },
  { term: "Bulletproof hosting", definition: "Hosting providers that ignore abuse complaints and takedown requests, used by attackers for C2 and malware distribution infrastructure.", objective: "3.1" },
  { term: "Velociraptor", definition: "Open-source endpoint visibility and forensics tool that runs queries across a whole fleet, e.g. to find every host with a given scheduled task or file hash.", objective: "3.1" },

  // 3.2 Outline the incident response process
  { term: "Containment", definition: "Incident response activities that limit damage and stop the spread of an incident, such as isolating hosts or disabling accounts.", objective: "3.2" },
  { term: "Eradication", definition: "Removing the cause of an incident, such as malware, persistence mechanisms and compromised accounts, and closing the exploited vulnerability.", objective: "3.2" },
  { term: "Recovery", definition: "Restoring affected systems to normal operation, verifying they are clean, and monitoring for reinfection.", objective: "3.2" },
  { term: "Incident response plan", definition: "Formal, management-approved document defining how an organization detects, responds to and recovers from incidents, including roles, severity levels and communications.", objective: "3.2" },
  { term: "CSIRT", definition: "Computer Security Incident Response Team: the group responsible for handling security incidents within an organization. CIRT means the same; CERT usually refers to external, national or government-affiliated teams.", objective: "3.2" },
  { term: "Tabletop exercise", definition: "Discussion-based exercise where participants talk through their response to a simulated incident scenario to find gaps in plans and roles.", objective: "3.2" },
  { term: "Jump bag", definition: "Prepared kit of tools and documents for incident responders, such as forensic laptop, write blockers, drives, cables, forms and contact lists.", objective: "3.2" },
  { term: "Business continuity plan", definition: "Plan for keeping essential business functions operating during and after a disruption.", objective: "3.2" },
  { term: "Disaster recovery plan", definition: "Plan for restoring IT systems, data and infrastructure after a disaster, part of business continuity.", objective: "3.2" },
  { term: "RTO", definition: "Recovery Time Objective: maximum acceptable time to restore a system or process after a disruption.", objective: "3.2" },
  { term: "RPO", definition: "Recovery Point Objective: maximum acceptable amount of data loss measured in time, which determines how often backups are taken.", objective: "3.2" },
  { term: "BIA", definition: "Business Impact Analysis: identifies critical business functions and the impact of their disruption, setting recovery priorities and objectives.", objective: "3.2" },
  { term: "Lessons learned", definition: "Structured, blameless post-incident review held soon after closure (typically within one to two weeks) covering what went well, what did not and what to change across people, process and technology, with tracked actions.", objective: "3.2" },
  { term: "Hot site", definition: "Fully equipped alternate site with current data that can take over operations almost immediately. Fastest and most expensive recovery option.", objective: "3.2" },
  { term: "Security event", definition: "Any observable occurrence in a system or network, such as a logon or a blocked connection. Most events are benign; only some become incidents.", objective: "3.2" },
  { term: "Security incident", definition: "A violation, or imminent threat of violation, of security policy, acceptable use policy or standard security practice, such as confirmed malware or a data breach.", objective: "3.2" },
  { term: "Incident response policy", definition: "High-level IR document setting expectations and obligations: what must be reported, response timelines and who is accountable. Procedures implement it.", objective: "3.2" },
  { term: "Incident response procedure", definition: "Step-by-step instructions for an IR task: who acts, on which system, in what order and how the result is verified.", objective: "3.2" },
  { term: "Walkthrough exercise", definition: "IR exercise in which the team reviews the plan step by step to confirm it is complete, current and understood.", objective: "3.2" },
  { term: "Mock incident", definition: "Simulation exercise in which responders actually carry out response steps against fake alerts and some systems. More realistic and costly than a tabletop.", objective: "3.2" },
  { term: "Full incident simulation", definition: "Organization-wide exercise using real people and systems, from technical containment to executive communication and legal notification. The most complete, expensive and disruptive test.", objective: "3.2" },
  { term: "CIRT", definition: "Cyber Incident Response Team: functionally the same as a CSIRT; the term is common in government and defense.", objective: "3.2" },
  { term: "Centralized IR team", definition: "IR model with a dedicated, full-time response team, suited to large organizations with high incident volume and 24/7 needs.", objective: "3.2" },
  { term: "Distributed IR team", definition: "IR model in which response duties are spread across existing IT and security staff who have other primary roles, common in mid-sized organizations.", objective: "3.2" },
  { term: "Hybrid IR team", definition: "IR model with a small permanent core team that activates staff from other departments as needed; flexible and well suited to cloud and DevSecOps environments.", objective: "3.2" },
  { term: "Incident commander", definition: "The IR lead and single decision maker during an incident: sets scope and priorities, approves escalation and briefs leadership.", objective: "3.2" },
  { term: "Communications liaison", definition: "IR role acting as the single point of contact with executives, legal, HR, PR and regulators, so messages are consistent and timed correctly.", objective: "3.2" },
  { term: "IR retainer", definition: "Pre-negotiated contract with an outside incident response firm that guarantees expert help quickly, without negotiating terms during a crisis.", objective: "3.2" },
  { term: "Triage", definition: "Rapidly classifying, prioritizing and routing alerts or incidents by severity and impact, combining confidence that a threat is real with its potential blast radius.", objective: "3.2" },
  { term: "Remediation (incident)", definition: "Fixing the root cause of an incident (patching, configuration change, compensating control) so the same attack cannot succeed again. Distinct from recovery, which restores function.", objective: "3.2" },
  { term: "Phased restoration", definition: "Recovery approach that brings back the most critical services first, monitors them closely for 24 to 48 hours, then restores the next tier.", objective: "3.2" },
  { term: "Communication plan", definition: "Part of the IR plan defining who communicates what, to whom, how often and through which channel during an incident, including out-of-band options.", objective: "3.2" },
  { term: "Need-to-know", definition: "Principle of sharing incident details only with people who require them to act, limiting leaks and avoiding tipping off the attacker or an insider.", objective: "3.2" },
  { term: "Warm site", definition: "Alternate site with hardware and connectivity ready but data needing to be restored. Slower and cheaper than a hot site, faster than a cold site.", objective: "3.2" },
  { term: "Cold site", definition: "Alternate site providing only space, power and cooling. The cheapest option with the longest recovery time.", objective: "3.2" },
  { term: "3-2-1 backup rule", definition: "Keep three copies of data on two different media types with one copy offsite; modern practice adds an immutable or offline copy against ransomware.", objective: "3.2" },

  // 3.3 Implement incident response techniques
  { term: "Chain of custody", definition: "Documented record of everyone who handled a piece of evidence, when and why, proving it was not tampered with and keeping it admissible.", objective: "3.3" },
  { term: "Legal hold", definition: "A requirement to preserve all relevant data when litigation or an investigation is expected, overriding normal deletion and retention policies.", objective: "3.3" },
  { term: "Order of volatility", definition: "The sequence for collecting evidence from most to least volatile: CPU registers and cache, memory, temporary files, disk, remote logs, then archival media.", objective: "3.3" },
  { term: "Write blocker", definition: "Hardware or software device that allows reading from a storage drive while preventing any writes, preserving original evidence.", objective: "3.3" },
  { term: "Forensic image", definition: "A bit-by-bit copy of storage media, including deleted and unallocated space, verified by hash to match the original.", objective: "3.3" },
  { term: "Integrity validation", definition: "Hashing evidence when collected and again later to prove it has not changed.", objective: "3.3" },
  { term: "Isolation", definition: "Cutting a compromised system off from the rest of the network, for example through EDR network isolation or a quarantine VLAN, while keeping it powered for analysis.", objective: "3.3" },
  { term: "Re-imaging", definition: "Wiping a system and reinstalling it from a known-good image, the most reliable way to remove a deep compromise.", objective: "3.3" },
  { term: "Volatility", definition: "Open-source memory forensics framework used to analyze RAM images for processes, network connections, injected code and other artifacts.", objective: "3.3" },
  { term: "Sanitization", definition: "Securely removing data from media so it cannot be recovered, through overwriting, cryptographic erase, degaussing or physical destruction.", objective: "3.3" },
  { term: "Root cause analysis", definition: "Investigation to find the underlying reason an incident occurred, so corrective action addresses the cause rather than the symptom.", objective: "3.3" },
  { term: "Five whys", definition: "Root cause technique of repeatedly asking why a problem occurred until reaching a fundamental process or control failure.", objective: "3.3" },
  { term: "Isolation security group", definition: "A cloud security group with no or minimal rules (for example forensic access only) that responders attach to a compromised instance to cut its network access while keeping it running for evidence.", objective: "3.3" },
  { term: "Volume snapshot", definition: "A point-in-time copy of a cloud disk taken during incident response to preserve evidence before an instance is changed, rebuilt or terminated.", objective: "3.3" },
  { term: "Session revocation", definition: "Invalidating existing sessions and refresh tokens for a user or role, so an attacker holding a stolen token is forced out. Needed in addition to resetting passwords or keys.", objective: "3.3" },
  { term: "Access key revocation", definition: "Deactivating or deleting a compromised cloud access key and issuing a replacement, followed by a review of audit logs for everything done with the old key.", objective: "3.3" },
  { term: "IMDSv2", definition: "AWS Instance Metadata Service version 2, which requires a session token obtained through a PUT request before metadata can be read, reducing the risk of credential theft through SSRF.", objective: "3.3" },
  { term: "Incident scope", definition: "Everything an incident touches or threatens: compromised systems, accounts, data and services, plus what containment actions will affect. Not the same as severity.", objective: "3.3" },
  { term: "Blast radius", definition: "The full set of systems, accounts, data and services an attacker touched or could reach from a compromised asset.", objective: "3.3" },
  { term: "Time normalization", definition: "Converting timestamps from all log sources to one reference, usually UTC, before building a timeline so events from different time zones are ordered correctly.", objective: "3.3" },
  { term: "Short-term containment", definition: "Immediate actions to stop an incident spreading, such as isolating hosts, blocking IPs or disabling accounts.", objective: "3.3" },
  { term: "Long-term containment", definition: "Temporary measures that let the business keep operating safely while eradication is prepared, such as extra filtering, alternate paths or compensating controls.", objective: "3.3" },
  { term: "Quarantine VLAN", definition: "An isolated network segment where suspect hosts are moved so they cannot reach production systems or the internet while investigation continues.", objective: "3.3" },
  { term: "Account isolation", definition: "Containing a compromised identity by disabling it, stripping its privileges or sensitive access, and revoking its sessions and tokens.", objective: "3.3" },
  { term: "Spoliation", definition: "Destruction or alteration of evidence relevant to litigation, whether negligent or intentional, e.g. letting log rotation delete data under a legal hold. It can lead to court sanctions.", objective: "3.3" },
  { term: "WORM storage", definition: "Write once, read many storage that prevents modification or deletion after writing; the preferred way to preserve evidence and audit logs.", objective: "3.3" },
  { term: "Evidence register", definition: "Case-level record of every evidence item: ID, description, acquisition time, analyst, source, hash, storage location, custody entries and legal hold status.", objective: "3.3" },
  { term: "FTK Imager", definition: "Free forensic tool for creating disk and memory images with built-in hash verification.", objective: "3.3" },
  { term: "dd", definition: "Unix command that copies data block by block, used to create bit-for-bit forensic images, e.g. dd if=/dev/sdb of=case.img bs=4M.", objective: "3.3" },
  { term: "Autopsy", definition: "Open-source graphical digital forensics platform built on The Sleuth Kit, used for file system analysis, keyword search and timeline building.", objective: "3.3" },
  { term: "WinPmem", definition: "Open-source memory acquisition tool for capturing RAM from live Windows systems.", objective: "3.3" },
  { term: "Magnet RAM Capture", definition: "Free tool for capturing the physical memory of a live Windows system for later analysis.", objective: "3.3" },
  { term: "AVML", definition: "Acquire Volatile Memory for Linux: Microsoft's open-source tool for capturing memory from live Linux systems.", objective: "3.3" },
  { term: "LiME", definition: "Linux Memory Extractor: a loadable kernel module for acquiring memory from Linux and Android systems.", objective: "3.3" },
  { term: "SHA-256", definition: "Cryptographic hash function producing a 256-bit digest; the modern standard for verifying evidence integrity because any change produces a different value.", objective: "3.3" },
  { term: "sha256sum", definition: "Linux command that computes SHA-256 hashes of files or devices, used to record and verify evidence integrity.", objective: "3.3" },
  { term: "certutil -hashfile", definition: "Windows command for computing a file hash, e.g. certutil -hashfile evidence.img SHA256.", objective: "3.3" },
  { term: "Read-only mount", definition: "Mounting a forensic image so it cannot be written to, e.g. mount -o loop,ro image.img /mnt, so analysis does not alter it.", objective: "3.3" },
  { term: "Persistence mechanism", definition: "Any method an attacker uses to keep access across reboots and credential changes, such as Run keys, scheduled tasks, services, cron jobs, SSH authorized_keys or web shells.", objective: "3.3" },
  { term: "Registry Run key", definition: "Windows registry location (Run and RunOnce under HKLM or HKCU) whose entries launch programs at startup or logon; a common persistence point (ATT&CK T1547.001).", objective: "3.3" },
  { term: "EDR remote response", definition: "EDR features (e.g. Falcon Real Time Response, Defender Live Response) that let responders kill processes, quarantine files and remove persistence remotely.", objective: "3.3" },
  { term: "krbtgt", definition: "The Active Directory account whose key signs Kerberos tickets. After a domain compromise its password is reset twice to invalidate forged golden tickets.", objective: "3.3" },
  { term: "Enhanced monitoring", definition: "A probation period of about 7 to 30 days after recovery with lower alert thresholds, stricter correlation and closer review of affected systems to catch re-compromise.", objective: "3.3" },
  { term: "Functional escalation", definition: "Bringing in specialists or other functions (forensics, cloud team, legal, PR) for expertise during an incident; also called lateral escalation.", objective: "3.3" },
  { term: "Hierarchical escalation", definition: "Moving an incident up the management chain to people with authority for business decisions; also called vertical escalation.", objective: "3.3" },
  { term: "Event ID 4648", definition: "Windows Security event: a logon was attempted using explicit credentials (e.g. runas or remote execution), useful for spotting lateral movement.", objective: "3.3" },
  { term: "Fishbone diagram", definition: "Ishikawa root cause diagram: the problem is the spine and contributing causes branch off under categories such as people, process, technology and environment.", objective: "3.3" },

  // 4.1 Explain vulnerability management reporting and communication
  { term: "Risk score", definition: "A value that ranks a vulnerability or asset by combining severity, exploitability, exposure and business impact for prioritization.", objective: "4.1" },
  { term: "Recurrence", definition: "A vulnerability that reappears after being remediated, often pointing to a process failure such as an outdated golden image.", objective: "4.1" },
  { term: "Compliance report", definition: "Report showing whether systems meet a specific standard or regulation, listing each check, status, evidence and exceptions for auditors and management.", objective: "4.1" },
  { term: "Action plan", definition: "A set of assigned, scheduled remediation tasks with owners and due dates that turns findings into work.", objective: "4.1" },
  { term: "MOU", definition: "Memorandum of Understanding: a generally non-binding agreement that sets expectations between parties, e.g. that a partner or MSP maintains a shared system, which can limit when or how you remediate it.", objective: "4.1" },
  { term: "SLA", definition: "Service Level Agreement: a formal, usually contractual and binding commitment, such as uptime guarantees or a vendor's obligation to patch criticals within 30 days. It can delay remediation; an internal target is an SLO, not an SLA.", objective: "4.1" },
  { term: "Legacy system", definition: "Outdated hardware or software that may no longer receive patches but is still needed by the business, often requiring compensating controls.", objective: "4.1" },
  { term: "KPI", definition: "Key Performance Indicator: a measurable value showing how well a program meets its goals, such as percentage of critical vulnerabilities fixed within SLO.", objective: "4.1" },
  { term: "Top 10 report", definition: "Summary of the most common or highest-risk vulnerabilities, hosts or business units, highlighting where remediation effort will have the most effect.", objective: "4.1" },
  { term: "Stakeholder", definition: "Any person or group with an interest in or responsibility for an outcome, such as system owners, executives, auditors and customers.", objective: "4.1" },
  { term: "Degrading functionality", definition: "A remediation inhibitor where a patch or hardening change would break or slow features that the business relies on.", objective: "4.1" },
  { term: "Remediation effectiveness", definition: "The share of remediated findings or incidents that stay fixed, for example the percentage of 'fixed' vulnerabilities that are clean on a validation rescan, or incidents that do not recur.", objective: "4.1" },
  { term: "SLA compliance rate", definition: "The percentage of findings remediated within the agreed time frame for their severity. Late fixes and open exceptions are reported separately.", objective: "4.1" },
  { term: "Mean time to remediate", definition: "For vulnerabilities, average time from discovery to verified fix, tracked by severity. For incidents, average time from containment until the root cause is fixed and operations are restored.", objective: "4.1" },
  { term: "Vulnerability dashboard", definition: "A visual summary of vulnerability data, such as open findings by severity, trends, SLA compliance and top exposures, filtered for each audience.", objective: "4.1" },
  { term: "Summary report", definition: "Periodic, concise vulnerability report for leadership and compliance showing top findings, remediation progress and trends.", objective: "4.1" },
  { term: "Detailed report", definition: "Full technical vulnerability report for remediation teams listing each finding with CVE, affected hosts, CVSS, evidence and fix.", objective: "4.1" },
  { term: "Risk scorecard", definition: "Visual summary of risk posture by system, business unit or organization, combining severity, asset criticality, exploitability, remediation velocity and compliance, for decision makers.", objective: "4.1" },
  { term: "RAG status", definition: "Red, amber, green rating used on scorecards and dashboards to show at a glance whether a metric is off track, at risk or on target.", objective: "4.1" },
  { term: "Compliance finding", definition: "A gap against a standard, regulation or policy requirement (e.g. weak SSH ciphers violating PCI DSS), often with no CVE. Carries audit risk.", objective: "4.1" },
  { term: "Plugin ID", definition: "Identifier of the scanner check (e.g. a Nessus plugin) that produced a finding, showing how it was detected and helping validate false positives.", objective: "4.1" },
  { term: "Remediation SLA", definition: "Agreed maximum time to fix findings by severity, commonly 15 days for critical, 30 for high, 90 for medium and 180 for low.", objective: "4.1" },
  { term: "Scan coverage", definition: "Percentage of known assets scanned within a period. Unscanned assets are unknown exposure, so low coverage makes other metrics misleading.", objective: "4.1" },
  { term: "Organizational governance", definition: "Remediation inhibitor arising from approval processes, change advisory board cadence and notice periods, or unclear ownership.", objective: "4.1" },
  { term: "Business process interruption", definition: "Remediation inhibitor where applying a fix requires downtime or reboots that a critical, often 24/7, business process cannot tolerate.", objective: "4.1" },
  { term: "Proprietary system", definition: "Vendor-controlled system (e.g. OT/ICS, medical device, appliance) that only the vendor may patch; changing it may void support, so remediation waits on the vendor.", objective: "4.1" },
  { term: "Patch availability", definition: "Remediation inhibitor where no fix exists yet (zero-day or end-of-life software), requiring compensating controls such as WAF rules, network restrictions and monitoring.", objective: "4.1" },
  { term: "CAB", definition: "Change advisory board: the group that reviews and approves changes; its schedule can delay remediation, so action plans record CAB status and the planned window.", objective: "4.1" },
  { term: "Nessus audit file", definition: "Compliance policy file (e.g. CIS, DISA STIG, PCI DSS) that lets Nessus check configuration settings and report pass, fail or warning results.", objective: "4.1" },
  { term: "Secure Score", definition: "Microsoft Defender for Cloud and Microsoft 365 posture score that rises as recommended security controls are implemented; used in executive reporting.", objective: "4.1" },

  // 4.2 Describe security operations, incident response reporting and communication
  { term: "Incident declaration", definition: "Formal decision that an event is a security incident, which activates the IR plan and starts internal and regulatory timelines.", objective: "4.2" },
  { term: "Escalation", definition: "Engaging more senior, specialized or external people when an incident exceeds your authority, expertise or capacity. Vertical (hierarchical) escalation goes up the management chain; lateral (functional) escalation brings in other teams such as legal or IT operations.", objective: "4.2" },
  { term: "Executive summary", definition: "Short, non-technical section of a report giving leadership what happened, business impact, status and key recommendations.", objective: "4.2" },
  { term: "Incident timeline", definition: "Chronological record of key incident events from initial compromise through detection, containment, eradication and recovery.", objective: "4.2" },
  { term: "After-action report", definition: "Full post-incident record: incident summary, timeline, technical analysis (mapped to ATT&CK), impact assessment, response evaluation and specific, owned recommendations. More detailed than the executive summary.", objective: "4.2" },
  { term: "MTTD", definition: "Mean Time to Detect: average time between the start of an incident and its detection. Lower values indicate better monitoring.", objective: "4.2" },
  { term: "MTTR", definition: "Ambiguous acronym. Mean time to respond: detection to the first containment action (e.g. isolating a host). Mean time to remediate: containment to root cause fixed and operations restored (e.g. re-imaging). Read the context to tell which is meant.", objective: "4.2" },
  { term: "Dwell time", definition: "How long an attacker remains undetected in an environment, from initial compromise to detection.", objective: "4.2" },
  { term: "Alert volume", definition: "The number of security alerts generated in a period, tracked with true and false positive rates to judge detection quality and staffing.", objective: "4.2" },
  { term: "Regulatory reporting", definition: "Mandatory notification of incidents to regulators within set deadlines, such as GDPR's 72-hour requirement for personal data breaches.", objective: "4.2" },
  { term: "Out-of-band communication", definition: "Using channels separate from potentially compromised systems, such as phone bridges or alternate messaging, during incident response.", objective: "4.2" },
  { term: "Breach notification", definition: "Informing affected individuals, regulators and other parties that personal data was compromised, as required by law or contract.", objective: "4.2" },
  { term: "False positive rate (SOC)", definition: "In SOC reporting, the share of alerts that turn out to be benign after triage, tracked per rule to guide tuning. High rates cause alert fatigue.", objective: "4.2" },
  { term: "MTTA", definition: "Mean time to acknowledge: the average time between an alert being raised and an analyst starting work on it.", objective: "4.2" },
  { term: "Mean time to contain", definition: "Average time from detection of an incident to its containment, showing how quickly the team limits damage. Closely related to mean time to respond; note that the acronym MTTC is also used for mean time to close.", objective: "4.2" },
  { term: "SOC dashboard", definition: "A display of operational metrics such as alert volume, queue age, MTTD, MTTA, MTTR and false positive rate, used by managers to spot workload and quality problems.", objective: "4.2" },
  { term: "Recurrence rate", definition: "The share of closed incidents or fixed vulnerabilities that return, a direct measure of whether eradication and remediation worked.", objective: "4.2" },
  { term: "Escalation matrix", definition: "Predefined table listing who to notify for each incident severity, with contact details, backup contacts and how long to wait before escalating further.", objective: "4.2" },
  { term: "Communication matrix", definition: "Table mapping each incident stakeholder to contact details, information type, update frequency and channel.", objective: "4.2" },
  { term: "Holding statement", definition: "Pre-approved, brief public or customer statement used early in an incident so staff do not speculate before the official communication is ready.", objective: "4.2" },
  { term: "OPSEC", definition: "Operational security: keeping incident information from unauthorized parties, including the attacker, through out-of-band channels, need-to-know and careful public statements.", objective: "4.2" },
  { term: "Coordinated cutover", definition: "Executing all containment actions at the same moment so the attacker has no time to react, switch persistence or accelerate exfiltration.", objective: "4.2" },
  { term: "GDPR", definition: "EU General Data Protection Regulation: protects personal data of people in the EU and requires notifying the supervisory authority within 72 hours of becoming aware of a qualifying breach.", objective: "4.2" },
  { term: "HIPAA Breach Notification Rule", definition: "US rule requiring covered entities to notify individuals within 60 days of discovering a PHI breach, the media when more than 500 residents of a state are affected, and HHS.", objective: "4.2" },
  { term: "PCI Forensic Investigator (PFI)", definition: "Investigator approved by the PCI Security Standards Council who must be engaged to examine a cardholder data breach.", objective: "4.2" },
  { term: "CCPA/CPRA", definition: "California Consumer Privacy Act and its amendment, the California Privacy Rights Act: among the strictest US state privacy and breach laws.", objective: "4.2" },
  { term: "FBI IC3", definition: "Internet Crime Complaint Center (ic3.gov): the FBI portal for reporting cybercrime such as ransomware, BEC and fraud.", objective: "4.2" },
  { term: "CISA", definition: "US Cybersecurity and Infrastructure Security Agency: accepts incident reports (cisa.gov/report), publishes advisories and maintains the KEV catalog.", objective: "4.2" },
  { term: "Response evaluation", definition: "AAR section assessing what worked and what did not during the response (detection delays, containment gaps, communication failures), written blame-free.", objective: "4.2" },
  { term: "Shift handover", definition: "Formal written and verbal transfer of situational awareness, open tasks and decision authority between shifts, signed off by both leads.", objective: "4.2" },
  { term: "Continuous incident log", definition: "Running, timestamped record of every action, finding, contact and decision with its reasoning and the analyst's name, kept in the case platform during an incident.", objective: "4.2" },
  { term: "Case management platform", definition: "System such as ServiceNow, TheHive or Jira Service Management that serves as the single source of truth for cases, evidence, actions and handovers.", objective: "4.2" },
  { term: "Follow-the-sun", definition: "SOC staffing model in which teams in different time zones hand work to each other so coverage is 24/7 during normal working hours.", objective: "4.2" },
  { term: "True positive rate", definition: "Share of alerts that were real threats: TP / total alerts x 100. Higher is better and shows detection fidelity.", objective: "4.2" },
  { term: "Benign positive", definition: "An alert triggered by a real event that is not a threat, such as an authorized penetration test. Counted separately from true and false positives.", objective: "4.2" },
  { term: "Mean time to close", definition: "MTTC: average time from detection to ticket closure, including documentation and approvals. Used in SLAs and executive reporting; note MTTC can also mean mean time to contain.", objective: "4.2" },
  { term: "Phishing click rate", definition: "Share of simulated phishing emails delivered that were clicked: clicks / delivered x 100. The main metric for human-layer risk and awareness effectiveness.", objective: "4.2" },
  { term: "Report rate", definition: "Share of phishing simulation recipients who reported the email. A rising report rate shows staff acting as sensors.", objective: "4.2" },
  { term: "Activity metric", definition: "A count of work done, such as patches applied or scans run. Shows effort, not effectiveness.", objective: "4.2" },
  { term: "Performance metric", definition: "A measure of how effective security work is against a goal, such as percentage of critical vulnerabilities fixed within SLA or MTTD.", objective: "4.2" },
  { term: "Balanced scorecard", definition: "Reporting several complementary metrics together so that improving or gaming one at the expense of others becomes visible.", objective: "4.2" },
  { term: "Risk-based alerting", definition: "Approach (e.g. in Splunk ES) where low-confidence detections add risk points to an asset or user and only crossing a threshold raises an alert, cutting volume and false positives.", objective: "4.2" },
  { term: "Detection sensitivity", definition: "How well detections catch real threats (fewer false negatives). Raising it usually lowers specificity.", objective: "4.2" },
  { term: "Detection specificity", definition: "How well detections avoid false alarms (fewer false positives). It trades off against sensitivity and is tuned to each asset's risk.", objective: "4.2" },
  { term: "Tactical threat intelligence", definition: "Short-term, IoC-heavy intelligence (daily or weekly) about active threats, for response teams to act on immediately.", objective: "4.2" },
  { term: "Operational threat intelligence", definition: "Intelligence about campaigns, emerging techniques and detection coverage (weekly or monthly), for security management planning near-term actions.", objective: "4.2" },
  { term: "Strategic threat intelligence", definition: "Long-term, non-technical intelligence on trends, business risk and investment (quarterly or annual), for executives and the board.", objective: "4.2" },
  { term: "IoC decay", definition: "Loss of value of indicators such as IPs and domains over time as attackers rotate infrastructure; TTPs stay useful much longer.", objective: "4.2" },
  { term: "NIST SP 800-55", definition: "NIST performance measurement guide for information security, the reference for designing a security metrics program.", objective: "4.2" },
  { term: "GoPhish", definition: "Open-source phishing simulation framework for running awareness campaigns and tracking clicks, credential submissions and reports.", objective: "4.2" },
  { term: "KnowBe4", definition: "Commercial security awareness training and phishing simulation platform that tracks click and report rates.", objective: "4.2" },
]
